import React, { useState, useEffect } from 'react';
import {
  Card,
  TextField,
  Button,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Grid,
  Typography,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Paper,
  Alert,
  CircularProgress,
  IconButton,
  Tooltip
} from '@mui/material';
import {
  Add as AddIcon,
  Search as SearchIcon,
  Refresh as RefreshIcon,
  Create as CreateIcon
} from '@mui/icons-material';
import { useForm, Controller } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import { useErpStore } from '../../store/erpStore';
import { OrderSuggestionData, OrderSuggestionFilters } from '../../types/erpTypes';

// Validierungsschema für Filter
const filterSchema: yup.ObjectSchema<OrderSuggestionFilters> = yup.object({
  articleGroup: yup.string().optional(),
  branch: yup.string().optional(),
  matchcode: yup.string().optional(),
  minStock: yup.number().min(0, 'Mindestbestand muss größer oder gleich 0 sein').optional(),
  maxStock: yup.number().min(0, 'Maximalbestand muss größer oder gleich 0 sein').optional()
}) as yup.ObjectSchema<OrderSuggestionFilters>;

interface OrderSuggestionProps {
  onSuggestionSelect?: (suggestion: OrderSuggestionData) => void;
  onOrderCreate?: (order: any) => void;
}

export const OrderSuggestion: React.FC<OrderSuggestionProps> = ({
  onSuggestionSelect,
  onOrderCreate
}) => {
  const {
    orderSuggestions,
    orderSuggestionFilters,
    orderSuggestionLoading,
    orderSuggestionError,
    fetchOrderSuggestions,
    createOrderFromSuggestion
  } = useErpStore();

  const [selectedSuggestions, setSelectedSuggestions] = useState<string[]>([]);

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors }
  } = useForm<OrderSuggestionFilters>({
    resolver: yupResolver(filterSchema)
  });

  // Initial laden
  useEffect(() => {
    fetchOrderSuggestions({});
  }, [fetchOrderSuggestions]);

  // Filter anwenden
  const onSubmitFilters = (filters: OrderSuggestionFilters) => {
    fetchOrderSuggestions(filters);
  };

  // Filter zurücksetzen
  const handleResetFilters = () => {
    reset();
    fetchOrderSuggestions({});
  };

  // Vorschlag auswählen
  const handleSuggestionSelect = (suggestion: OrderSuggestionData) => {
    if (onSuggestionSelect) {
      onSuggestionSelect(suggestion);
    }
  };

  // Bestellung aus Vorschlag erstellen
  const handleCreateOrder = async (suggestion: OrderSuggestionData) => {
    try {
      await createOrderFromSuggestion(suggestion);
      if (onOrderCreate) {
        onOrderCreate(suggestion);
      }
    } catch (error) {
      console.error('Fehler beim Erstellen der Bestellung:', error);
    }
  };

  // Mehrere Vorschläge auswählen
  const handleSelectSuggestion = (articleNumber: string) => {
    setSelectedSuggestions(prev => 
      prev.includes(articleNumber) 
        ? prev.filter(id => id !== articleNumber)
        : [...prev, articleNumber]
    );
  };

  // Alle ausgewählten Vorschläge zu Bestellung
  const handleCreateOrderFromSelected = async () => {
    const selectedSuggestionsData = orderSuggestions.filter(s => 
      selectedSuggestions.includes(s.articleNumber)
    );

    for (const suggestion of selectedSuggestionsData) {
      await handleCreateOrder(suggestion);
    }

    setSelectedSuggestions([]);
  };

  return (
    <Card className="p-6 max-w-7xl mx-auto">
      <Typography variant="h5" className="mb-6 text-gray-800">
        Bestellvorschlag / Bestellung / Lieferantenstamm
      </Typography>

      {/* Filter-Bereich */}
      <Paper className="p-4 mb-6 bg-gray-50">
        <Typography variant="h6" className="mb-4">
          Filter
        </Typography>

        <form onSubmit={handleSubmit(onSubmitFilters)}>
          <Grid container spacing={3}>
            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="articleGroup"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Artikel-Gruppe"
                    fullWidth
                    variant="outlined"
                    size="small"
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="branch"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Niederlassung"
                    fullWidth
                    variant="outlined"
                    size="small"
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="matchcode"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Matchcode"
                    fullWidth
                    variant="outlined"
                    size="small"
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="minStock"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Min.-Bestand"
                    type="number"
                    fullWidth
                    variant="outlined"
                    size="small"
                    error={!!errors.minStock}
                    helperText={errors.minStock?.message}
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="maxStock"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Max.-Bestand"
                    type="number"
                    fullWidth
                    variant="outlined"
                    size="small"
                    error={!!errors.maxStock}
                    helperText={errors.maxStock?.message}
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <div className="flex space-x-2">
                <Button
                  type="submit"
                  variant="contained"
                  startIcon={<SearchIcon />}
                  size="small"
                >
                  Suchen
                </Button>
                <Button
                  type="button"
                  variant="outlined"
                  startIcon={<RefreshIcon />}
                  size="small"
                  onClick={handleResetFilters}
                >
                  Zurücksetzen
                </Button>
              </div>
            </Grid>
          </Grid>
        </form>
      </Paper>

      {/* Aktions-Buttons */}
      <div className="flex justify-between items-center mb-4">
        <Typography variant="h6">
          Bestellvorschlagsliste ({orderSuggestions.length} Einträge)
        </Typography>

        <div className="flex space-x-2">
          {selectedSuggestions.length > 0 && (
            <Button
              variant="contained"
              startIcon={<CreateIcon />}
              onClick={handleCreateOrderFromSelected}
              className="bg-green-600 hover:bg-green-700"
            >
              Bestellung aus {selectedSuggestions.length} Vorschlägen erstellen
            </Button>
          )}
        </div>
      </div>

      {/* Fehler-Anzeige */}
      {orderSuggestionError && (
        <Alert severity="error" className="mb-4">
          {orderSuggestionError}
        </Alert>
      )}

      {/* Lade-Indikator */}
      {orderSuggestionLoading && (
        <div className="flex justify-center items-center py-8">
          <CircularProgress />
        </div>
      )}

      {/* Tabelle */}
      {!orderSuggestionLoading && (
        <Table className="w-full border-collapse">
          <TableHead>
            <TableRow className="bg-gray-100">
              <TableCell className="font-semibold">Auswahl</TableCell>
              <TableCell className="font-semibold">Lager</TableCell>
              <TableCell className="font-semibold">Artikel-Nr.</TableCell>
              <TableCell className="font-semibold">Bezeichnung</TableCell>
              <TableCell className="font-semibold">Bestand</TableCell>
              <TableCell className="font-semibold">Min.-Best.</TableCell>
              <TableCell className="font-semibold">Max.-Best.</TableCell>
              <TableCell className="font-semibold">Verkauf</TableCell>
              <TableCell className="font-semibold">Vorschlag</TableCell>
              <TableCell className="font-semibold">Einkauf</TableCell>
              <TableCell className="font-semibold">Matchcode</TableCell>
              <TableCell className="font-semibold">Aktionen</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {orderSuggestions.map((suggestion) => (
              <TableRow 
                key={suggestion.articleNumber}
                className="hover:bg-gray-50"
              >
                <TableCell>
                  <input
                    type="checkbox"
                    checked={selectedSuggestions.includes(suggestion.articleNumber)}
                    onChange={() => handleSelectSuggestion(suggestion.articleNumber)}
                    className="w-4 h-4"
                  />
                </TableCell>
                <TableCell>{suggestion.warehouse}</TableCell>
                <TableCell className="font-mono">{suggestion.articleNumber}</TableCell>
                <TableCell>
                  <div>
                    <div className="font-medium">{suggestion.description1}</div>
                    {suggestion.description2 && (
                      <div className="text-sm text-gray-600">{suggestion.description2}</div>
                    )}
                  </div>
                </TableCell>
                <TableCell className="text-right">{suggestion.stock}</TableCell>
                <TableCell className="text-right">{suggestion.minStock}</TableCell>
                <TableCell className="text-right">{suggestion.maxStock}</TableCell>
                <TableCell className="text-right">{suggestion.sales}</TableCell>
                <TableCell className="text-right font-semibold text-blue-600">
                  {suggestion.suggestion}
                </TableCell>
                <TableCell className="text-right">{suggestion.purchase}</TableCell>
                <TableCell className="font-mono text-sm">{suggestion.matchcode}</TableCell>
                <TableCell>
                  <div className="flex space-x-1">
                    <Tooltip title="Vorschlag auswählen">
                      <IconButton
                        size="small"
                        onClick={() => handleSuggestionSelect(suggestion)}
                        className="text-blue-600"
                      >
                        <AddIcon />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Bestellung erstellen">
                      <IconButton
                        size="small"
                        onClick={() => handleCreateOrder(suggestion)}
                        className="text-green-600"
                      >
                        <CreateIcon />
                      </IconButton>
                    </Tooltip>
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}

      {/* Keine Daten */}
      {!orderSuggestionLoading && orderSuggestions.length === 0 && (
        <Alert severity="info" className="mt-4">
          Keine Bestellvorschläge gefunden. Passen Sie die Filter an oder erstellen Sie neue Vorschläge.
        </Alert>
      )}

      {/* Zusätzliche Informationen */}
      <Paper className="p-4 mt-6 bg-blue-50">
        <Typography variant="h6" className="mb-2 text-blue-800">
          Informationen
        </Typography>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm text-blue-700">
          <div>
            <strong>Artikel-Gruppe:</strong> Gruppierung der Artikel nach Kategorien
          </div>
          <div>
            <strong>Niederlassung:</strong> Standort/Zweigstelle
          </div>
          <div>
            <strong>Matchcode:</strong> Suchcode für schnelle Artikelfindung
          </div>
          <div>
            <strong>Min.-Bestand:</strong> Mindestbestand für automatische Bestellvorschläge
          </div>
          <div>
            <strong>Max.-Bestand:</strong> Maximalbestand für Lageroptimierung
          </div>
          <div>
            <strong>Vorschlag:</strong> Automatisch berechnete Bestellmenge
          </div>
        </div>
      </Paper>
    </Card>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Card,
  TextField,
  Button,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Grid,
  Typography,
  Tabs,
  Tab,
  Checkbox,
  FormControlLabel,
  Paper,
  Alert,
  CircularProgress,
  IconButton,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Divider,
  FormControl,
  InputLabel,
  Select,
  MenuItem
} from '@mui/material';
import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  Save as SaveIcon,
  Cancel as CancelIcon,
  Print as PrintIcon,
  FileCopy as FileCopyIcon
} from '@mui/icons-material';
import { useForm, Controller } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import { useErpStore } from '../../store/erpStore';
import { 
  PurchaseOrderData, 
  PurchaseOrderPosition, 
  DocumentReference,
  PaymentTerms,
  UnitType,
  PaymentMethod
} from '../../types/erpTypes';

// Validierungsschema für Bestellung
const purchaseOrderSchema: yup.ObjectSchema<PurchaseOrderData> = yup.object({
  creditorAccountNumber: yup.string().required('Kreditor-Konto-Nr. ist erforderlich'),
  branch: yup.string().required('Niederlassung ist erforderlich'),
  costCenter: yup.string().required('Kostenträger ist erforderlich'),
  commission: yup.string().required('Kommission ist erforderlich'),
  supplier: yup.string().required('Lieferant ist erforderlich'),
  latestDeliveryDate: yup.date().required('Lieferdatum ist erforderlich'),
  loadingDeadline: yup.date().required('Lade-Termin ist erforderlich'),
  loadingDate: yup.date().required('Lade-Datum ist erforderlich'),
  orderNumber: yup.string().required('Bestell-Nr. ist erforderlich'),
  orderDate: yup.date().required('Bestell-Datum ist erforderlich'),
  operator: yup.string().required('Bediener ist erforderlich'),
  completed: yup.boolean(),
  additionalInfo: yup.string()
}) as yup.ObjectSchema<PurchaseOrderData>;

// Validierungsschema für Position
const positionSchema = yup.object({
  articleNumber: yup.string().required('Artikel-Nr. ist erforderlich'),
  supplier: yup.string().required('Lieferant ist erforderlich'),
  description: yup.string().required('Bezeichnung ist erforderlich'),
  quantity: yup.number().positive('Menge muss größer als 0 sein').required('Menge ist erforderlich'),
  packageQuantity: yup.number().positive('Gebindemenge muss größer als 0 sein').required('Gebindemenge ist erforderlich'),
  packageUnit: yup.string().required('Gebindeeinheit ist erforderlich'),
  stock: yup.number().min(0, 'Bestand darf nicht negativ sein').required('Bestand ist erforderlich'),
  price: yup.number().positive('Preis muss größer als 0 sein').required('Preis ist erforderlich'),
  contract: yup.string().required('Kontrakt ist erforderlich')
});

interface PurchaseOrderProps {
  mode: 'create' | 'edit' | 'view';
  initialData?: PurchaseOrderData;
  onSave?: (order: PurchaseOrderData) => void;
  onCancel?: () => void;
}

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`purchase-order-tabpanel-${index}`}
      aria-labelledby={`purchase-order-tab-${index}`}
      {...other}
    >
      {value === index && <div className="py-4">{children}</div>}
    </div>
  );
}

export const PurchaseOrder: React.FC<PurchaseOrderProps> = ({
  mode,
  initialData,
  onSave,
  onCancel
}) => {
  const {
    currentPurchaseOrder,
    purchaseOrderLoading,
    purchaseOrderError,
    createPurchaseOrder,
    updatePurchaseOrder,
    addPurchaseOrderPosition,
    updatePurchaseOrderPosition,
    deletePurchaseOrderPosition
  } = useErpStore();

  const [tabValue, setTabValue] = useState(0);
  const [positions, setPositions] = useState<PurchaseOrderPosition[]>(initialData?.positions || []);
  const [positionDialogOpen, setPositionDialogOpen] = useState(false);
  const [editingPosition, setEditingPosition] = useState<PurchaseOrderPosition | null>(null);
  const [paymentTerms, setPaymentTerms] = useState<PaymentTerms>(
    initialData?.paymentTerms || {
      paymentMethod: PaymentMethod.BANK_TRANSFER,
      paymentDeadline: 30,
      discountDays: 14,
      discountPercent: 2,
      notes: ''
    }
  );

  const {
    control,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
    reset
  } = useForm<PurchaseOrderData>({
    resolver: yupResolver(purchaseOrderSchema),
    defaultValues: {
      creditorAccountNumber: initialData?.creditorAccountNumber || '',
      branch: initialData?.branch || '',
      costCenter: initialData?.costCenter || '',
      commission: initialData?.commission || '',
      supplier: initialData?.supplier || '',
      latestDeliveryDate: initialData?.latestDeliveryDate || new Date(),
      loadingDeadline: initialData?.loadingDeadline || new Date(),
      loadingDate: initialData?.loadingDate || new Date(),
      orderNumber: initialData?.orderNumber || `BO-${Date.now()}`,
      orderDate: initialData?.orderDate || new Date(),
      operator: initialData?.operator || '',
      completed: initialData?.completed || false,
      additionalInfo: initialData?.additionalInfo || '',
      references: initialData?.references || [],
      totalAmount: initialData?.totalAmount || 0,
      netAmount: initialData?.netAmount || 0,
      vatAmount: initialData?.vatAmount || 0
    }
  });

  // Position-Form
  const {
    control: positionControl,
    handleSubmit: handlePositionSubmit,
    reset: resetPosition,
    formState: { errors: positionErrors }
  } = useForm({
    resolver: yupResolver(positionSchema)
  });

  // Tab-Handler
  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  // Position hinzufügen
  const handleAddPosition = () => {
    setEditingPosition(null);
    resetPosition({
      position: positions.length + 1,
      articleNumber: '',
      supplier: '',
      description: '',
      quantity: 0,
      packageQuantity: 0,
      packageUnit: UnitType.PIECE,
      stock: 0,
      price: 0,
      contract: '',
      netAmount: 0
    } as any);
    setPositionDialogOpen(true);
  };

  // Position bearbeiten
  const handleEditPosition = (position: PurchaseOrderPosition) => {
    setEditingPosition(position);
    resetPosition(position);
    setPositionDialogOpen(true);
  };

  // Position löschen
  const handleDeletePosition = (positionId: string) => {
    setPositions(prev => prev.filter(p => p.id !== positionId));
  };

  // Position speichern
  const handleSavePosition = (positionData: PurchaseOrderPosition) => {
    const positionWithId = {
      ...positionData,
      id: editingPosition?.id || `pos-${Date.now()}-${Math.random()}`
    };

    if (editingPosition) {
      // Position aktualisieren
      setPositions(prev => prev.map(p => p.id === editingPosition.id ? positionWithId : p));
    } else {
      // Neue Position hinzufügen
      setPositions(prev => [...prev, positionWithId]);
    }
    setPositionDialogOpen(false);
    setEditingPosition(null);
  };

  // Gesamtbeträge berechnen
  const calculateTotals = () => {
    const netAmount = positions.reduce((sum, pos) => sum + (pos.quantity * pos.price), 0);
    const vatAmount = netAmount * 0.19; // 19% MwSt
    const totalAmount = netAmount + vatAmount;

    // Diese Felder sind nicht Teil des Hauptforms, daher verwenden wir setValue nicht
    // Stattdessen speichern wir sie im State
    (setValue as any)('netAmount', netAmount);
    (setValue as any)('vatAmount', vatAmount);
    (setValue as any)('totalAmount', totalAmount);
  };

  // Bestellung speichern
  const onSubmit = async (data: PurchaseOrderData) => {
    try {
      const orderData = {
        ...data,
        positions: positions,
        paymentTerms: paymentTerms
      };

      if (mode === 'create') {
        await createPurchaseOrder(orderData);
      } else if (mode === 'edit' && initialData?.id) {
        await updatePurchaseOrder(initialData.id, orderData);
      }

      if (onSave) {
        onSave(orderData);
      }
    } catch (error) {
      console.error('Fehler beim Speichern der Bestellung:', error);
    }
  };

  // Bestellung drucken
  const handlePrint = async () => {
    try {
      // TODO: Implementiere Druck-Funktionalität
      console.log('Drucke Bestellung...');
    } catch (error) {
      console.error('Fehler beim Drucken:', error);
    }
  };

  // Bestellung kopieren
  const handleCopy = () => {
    const copiedOrder = {
      ...initialData,
      id: undefined,
      orderNumber: `BO-${Date.now()}`,
      orderDate: new Date(),
      positions: positions.map(pos => ({ ...pos, id: `pos-${Date.now()}-${Math.random()}` }))
    };
    // Verwende die reset Funktion aus dem useForm Hook
    (reset as any)(copiedOrder as PurchaseOrderData);
  };

  return (
    <Card className="p-6 max-w-7xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <Typography variant="h5" className="text-gray-800">
          {mode === 'create' ? 'Bestellung erstellen' : 
           mode === 'edit' ? 'Bestellung bearbeiten' : 'Bestellung anzeigen'}
        </Typography>

        <div className="flex space-x-2">
          <Button
            variant="outlined"
            startIcon={<PrintIcon />}
            onClick={handlePrint}
            disabled={mode === 'create'}
          >
            Drucken
          </Button>
          <Button
            variant="outlined"
            startIcon={<FileCopyIcon />}
            onClick={handleCopy}
            disabled={mode === 'create'}
          >
            Kopieren
          </Button>
          <Button
            variant="outlined"
            startIcon={<CancelIcon />}
            onClick={onCancel}
          >
            Abbrechen
          </Button>
          <Button
            type="submit"
            variant="contained"
            startIcon={<SaveIcon />}
            onClick={handleSubmit(onSubmit)}
            disabled={mode === 'view'}
            data-testid="save-button"
          >
            Speichern
          </Button>
        </div>
      </div>

      {/* Fehler-Anzeige */}
      {purchaseOrderError && (
        <Alert severity="error" className="mb-4">
          {purchaseOrderError}
        </Alert>
      )}

      {/* Lade-Indikator */}
      {purchaseOrderLoading && (
        <div className="flex justify-center items-center py-8">
          <CircularProgress />
        </div>
      )}

      <form onSubmit={handleSubmit(onSubmit)}>
        {/* Kopfbereich */}
        <Paper className="p-4 mb-6">
          <Typography variant="h6" className="mb-4">
            Bestelldaten
          </Typography>

          <Grid container spacing={3}>
            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="creditorAccountNumber"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Kreditor-Konto-Nr."
                    fullWidth
                    required
                    error={!!errors.creditorAccountNumber}
                    helperText={errors.creditorAccountNumber?.message}
                    disabled={mode === 'view'}
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="branch"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Niederlassung"
                    fullWidth
                    required
                    error={!!errors.branch}
                    helperText={errors.branch?.message}
                    disabled={mode === 'view'}
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="costCenter"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Kostenträger"
                    fullWidth
                    required
                    error={!!errors.costCenter}
                    helperText={errors.costCenter?.message}
                    disabled={mode === 'view'}
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="commission"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Kommission"
                    fullWidth
                    required
                    error={!!errors.commission}
                    helperText={errors.commission?.message}
                    disabled={mode === 'view'}
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="supplier"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="Lieferant"
                    fullWidth
                    required
                    error={!!errors.supplier}
                    helperText={errors.supplier?.message}
                    disabled={mode === 'view'}
                  />
                )}
              />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Controller
                name="latestDeliveryDate"
                control={control}
                render={({ field }) => (
                  <TextField
                    {...field}
                    label="spät. Liefer-Datum"
                    type="date"
                    fullWidth
                    required
                    error={!!errors.latestDeliveryDate}
                    helperText={errors.latestDeliveryDate?.message}
                    disabled={mode === 'view'}
