      await createInventoryItem({
        name: createData.name || '',
        sku: createData.sku || '',
        quantity: parseInt(createData.quantity) || 0,
        unit_price: parseFloat(createData.unit_price) || 0,
        location: createData.location || '',
        category: createData.category || 'general',
        status: 'in_stock'
