import axios, { AxiosResponse } from 'axios';
import {
  // Bestellvorschlag
  OrderSuggestionData,
  OrderSuggestionFilters,

  // Bestellung
  PurchaseOrderData,
  PurchaseOrderPosition,

  // Lieferanten-Angebot
  SupplierOfferData,
  SupplierOfferPosition,

  // Anfrage
  InquiryData,
  InquiryPosition,

  // Lieferschein
  DeliveryNoteData,
