import React, { Component } from 'react';
import type { ErrorInfo, ReactNode } from 'react';
import { Alert, Button, Box, Typography } from '@mui/material';
// ✅ NEU: Import der standardisierten UI-Komponenten
import { StandardButton } from './forms/FormStandardization';
import { StandardMessage } from './ui/UIStandardization';
import { UI_LABELS } from './ui/UIStandardization';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error;
}

class SentryErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Error Boundary caught an error:', error, errorInfo);

    // Track error with Last9 if available
    if (typeof window !== 'undefined' && (window as any).last9Metrics) {
      (window as any).last9Metrics.trackError(error, {
        component: 'ErrorBoundary',
        errorInfo: JSON.stringify(errorInfo)
      });
    }
  }

  render() {
    if (this.state.hasError) {
      return (
        <Box sx={{ p: 4, textAlign: 'center' }}>
          <Box sx={{ mb: 4 }}>
            <StandardMessage
              type="error"
              title={UI_LABELS.ERRORS.TITLE}
              message={UI_LABELS.ERRORS.DESCRIPTION}
            />
          </Box>
          <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center', flexWrap: 'wrap' }}>
            <StandardButton
              variant="contained"
              onClick={() => window.location.reload()}
              sx={{ mr: 2 }}
            >
              {UI_LABELS.ACTIONS.RELOAD_PAGE}
            </StandardButton>
            <StandardButton
              variant="outlined"
              onClick={() => this.setState({ hasError: false })}
            >
              {UI_LABELS.ACTIONS.RETRY}
            </StandardButton>
          </Box>
        </Box>
      );
    }

    return this.props.children;
  }
}

export default SentryErrorBoundary;

import React from 'react';
import {
  Table as MuiTable,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Typography,
  Box,
  Skeleton,
  IconButton
} from '@mui/material';
import { Sort, Inbox } from '@mui/icons-material';
// ✅ NEU: Import der standardisierten UI-Komponenten
import { UI_LABELS } from './ui/UIStandardization';

interface Column<T> {
  key: string;
  header: string;
  render?: (value: any, row: T) => React.ReactNode;
  sortable?: boolean;
  width?: string;
}

interface TableProps<T> {
  data: T[];
  columns: Column<T>[];
  onRowClick?: (row: T) => void;
  loading?: boolean;
  emptyMessage?: string;
  className?: string;
}

export function Table<T>({
  data,
  columns,
  onRowClick,
  loading = false,
  emptyMessage = 'Keine Daten verfügbar',
  className,
}: TableProps<T>) {
  if (loading) {
    return (
      <Paper sx={{ p: 2 }}>
        <Box>
          <Skeleton variant="rectangular" height={32} sx={{ mb: 2 }} />
          {[...Array(5)].map((_, i) => (
            <Skeleton key={i} variant="rectangular" height={48} sx={{ mb: 1 }} />
          ))}
        </Box>
      </Paper>
    );
  }

  if (data.length === 0) {
    return (
      <Paper sx={{ p: 6, textAlign: 'center' }}>
        <Inbox sx={{ fontSize: 48, color: 'grey.400', mb: 2 }} />
        <Typography variant="body1" color="text.secondary">
          {emptyMessage}
        </Typography>
      </Paper>
    );
  }

  return (
    <Paper sx={{ overflow: 'hidden' }} className={className}>
      <TableContainer>
        <MuiTable>
          <TableHead>
            <TableRow>
              {columns.map((column) => (
                <TableCell
                  key={column.key}
                  sx={{
                    px: 3,
                    py: 1.5,
                    fontSize: '0.75rem',
                    fontWeight: 600,
                    textTransform: 'uppercase',
                    letterSpacing: '0.5px',
                    color: 'text.secondary',
                    width: column.width
                  }}
                >
                  <Box display="flex" alignItems="center" gap={0.5}>
                    <Typography variant="caption" fontWeight="medium">
                      {column.header}
                    </Typography>
                    {column.sortable && (
                      <IconButton size="small" sx={{ p: 0 }}>
                        <Sort fontSize="small" />
                      </IconButton>
                    )}
                  </Box>
                </TableCell>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {data.map((row, rowIndex) => (
              <TableRow
                key={rowIndex}
                sx={{
                  '&:hover': { backgroundColor: 'action.hover' },
                  cursor: onRowClick ? 'pointer' : 'default',
                  transition: 'background-color 0.2s'
                }}
                onClick={() => onRowClick?.(row)}
              >
                {columns.map((column) => (
                  <TableCell
                    key={column.key}
                    sx={{
                      px: 3,
                      py: 2,
                      fontSize: '0.875rem',
                      color: 'text.primary'
                    }}
                  >
                    {column.render
                      ? column.render((row as any)[column.key], row)
                      : (row as any)[column.key]}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </MuiTable>
      </TableContainer>
    </Paper>
  );
}

import React from 'react';
import { Card, Typography, Box, Chip } from '@mui/material';
import { 
  Security as SecurityIcon,
  CheckCircle as CheckCircleIcon,
  Warning as WarningIcon,
  Error as ErrorIcon,
  Info as InfoIcon
} from '@mui/icons-material';
// ✅ NEU: Import der standardisierten UI-Komponenten
import { StatusChip } from './ui/UIStandardization';
import { UI_LABELS } from './ui/UIStandardization';

export interface TrustIndicatorProps {
  title?: string;
  description?: string;
  level: 'high' | 'medium' | 'low' | 'critical' | 'fact' | 'assumption' | 'uncertain';
  value?: string | number;
  unit?: string;
  trend?: 'up' | 'down' | 'stable';
  lastUpdated?: string;
  details?: string[];
  className?: string;
  confidence?: number;
}

export type TrustLevel = 'high' | 'medium' | 'low' | 'critical' | 'fact' | 'assumption' | 'uncertain';

const TrustIndicator: React.FC<TrustIndicatorProps> = ({
  title,
  description,
  level,
  value,
  unit,
  trend,
  lastUpdated,
  details,
  className,
  confidence
}) => {
  // ✅ REFAKTORIERT: Verwendung von StatusChip für Level-Anzeige
  const getLevelStatus = (level: string): keyof typeof UI_LABELS.STATUS => {
    switch (level) {
      case 'high':
      case 'fact':
        return 'ACTIVE';
      case 'medium':
      case 'assumption':
        return 'PENDING';
      case 'low':
      case 'uncertain':
        return 'SUSPENDED';
      case 'critical':
        return 'ERROR';
      default:
        return 'UNKNOWN';
    }
  };

  const getLevelIcon = (level: string) => {
    switch (level) {
      case 'high':
      case 'fact':
        return <CheckCircleIcon />;
      case 'medium':
      case 'assumption':
        return <WarningIcon />;
      case 'low':
      case 'uncertain':
      case 'critical':
        return <ErrorIcon />;
      default:
        return <InfoIcon />;
    }
  };

  const getTrendIcon = (trend?: string) => {
    if (!trend) return null;

    switch (trend) {
      case 'up':
        return <span style={{ color: '#4caf50' }}>↗</span>;
      case 'down':
        return <span style={{ color: '#f44336' }}>↘</span>;
      case 'stable':
        return <span style={{ color: '#ff9800' }}>→</span>;
      default:
        return null;
    }
  };

  const levelStatus = getLevelStatus(level);
  const levelIcon = getLevelIcon(level);

  return (
    <Card 
      className={`trust-indicator ${className || ''}`}
      sx={{
        p: 2,
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        border: 2,
        borderColor: `${levelStatus}.main`,
        backgroundColor: `${levelStatus}.50`,
        transition: 'all 0.3s ease',
        '&:hover': {
          transform: 'translateY(-2px)',
          boxShadow: 3
        }
      }}
    >
      <Box display="flex" alignItems="center" mb={1}>
        <Box sx={{ color: `${levelStatus}.main`, mr: 1 }}>
          {levelIcon}
        </Box>
        {title && (
          <Typography 
            variant="h6" 
            component="h3"
            sx={{ 
              color: `${levelStatus}.main`,
              fontWeight: 600,
              flex: 1
            }}
          >
            {title}
          </Typography>
        )}
        <StatusChip 
          status={levelStatus}
          size="small"
        />
      </Box>

      {description && (
        <Typography 
          variant="body2" 
          sx={{ 
            color: 'text.secondary',
            mb: 2,
            flex: 1
          }}
        >
          {description}
        </Typography>
      )}

      {value !== undefined && (
        <Box display="flex" alignItems="center" mb={1}>
          <Typography 
            variant="h4" 
            component="span"
            sx={{ 
              color: `${levelStatus}.main`,
              fontWeight: 700,
              mr: 0.5
            }}
          >
            {value}
          </Typography>
          {unit && (
            <Typography 
              variant="body2" 
              sx={{ color: 'text.secondary' }}
            >
              {unit}
            </Typography>
          )}
          {trend && (
            <Box ml={1}>
              {getTrendIcon(trend)}
            </Box>
          )}
        </Box>
      )}

      {details && details.length > 0 && (
        <Box mt={1}>
          {details.map((detail, index) => (
            <Typography 
              key={index}
              variant="caption" 
              sx={{ 
                display: 'block',
                color: 'text.secondary',
                fontSize: '0.75rem'
              }}
            >
              • {detail}
            </Typography>
          ))}
        </Box>
      )}

      {lastUpdated && (
        <Typography 
          variant="caption" 
          sx={{ 
            color: 'text.disabled',
            fontSize: '0.7rem',
            mt: 1,
            display: 'block'
          }}
        >
          {UI_LABELS.MESSAGES.LAST_UPDATE}: {lastUpdated}
        </Typography>
      )}
    </Card>
  );
};

export default TrustIndicator;
export { TrustIndicator };

