import React from 'react';
import { Box, Typography, LinearProgress, Chip } from '@mui/material';
import { CheckCircle as CheckIcon, Warning as WarningIcon, Error as ErrorIcon } from '@mui/icons-material';

interface ConfidenceIndicatorProps {
  confidence: number;
  showPercentage?: boolean;
  showIcon?: boolean;
  size?: 'small' | 'medium' | 'large';
  variant?: 'progress' | 'chip' | 'text';
  className?: string;
}

export const ConfidenceIndicator: React.FC<ConfidenceIndicatorProps> = ({
  confidence,
  showPercentage = true,
  showIcon = true,
  size = 'medium',
  variant = 'progress',
  className = ''
}) => {
  const percentage = Math.round(confidence * 100);

  const getConfidenceColor = (conf: number) => {
    if (conf >= 0.8) return 'success';
    if (conf >= 0.6) return 'warning';
    return 'error';
  };

  const getConfidenceIcon = (conf: number) => {
    if (conf >= 0.8) return <CheckIcon />;
    if (conf >= 0.6) return <WarningIcon />;
    return <ErrorIcon />;
  };

  const getConfidenceLabel = (conf: number) => {
    if (conf >= 0.8) return 'Hoch';
    if (conf >= 0.6) return 'Mittel';
    return 'Niedrig';
  };

  const getSizeStyles = () => {
    switch (size) {
      case 'small':
        return { height: 8, fontSize: '0.75rem' };
      case 'large':
        return { height: 12, fontSize: '1rem' };
      default:
        return { height: 10, fontSize: '0.875rem' };
    }
  };

  if (variant === 'chip') {
    return (
      <Chip
        icon={showIcon ? getConfidenceIcon(confidence) : undefined}
        label={showPercentage ? `${percentage}%` : getConfidenceLabel(confidence)}
        color={getConfidenceColor(confidence) as any}
        size={size === 'small' ? 'small' : 'medium'}
        className={className}
      />
    );
  }

  if (variant === 'text') {
    return (
      <Box className={`flex items-center space-x-1 ${className}`}>
        {showIcon && getConfidenceIcon(confidence)}
        <Typography
          variant={size === 'small' ? 'caption' : 'body2'}
          color={`${getConfidenceColor(confidence)}.main`}
          className="font-medium"
        >
          {showPercentage ? `${percentage}%` : getConfidenceLabel(confidence)}
        </Typography>
      </Box>
    );
  }

  // Default: progress variant
  return (
    <Box className={`flex items-center space-x-2 ${className}`}>
      <Box className="flex-1">
        <LinearProgress
          variant="determinate"
          value={percentage}
          color={getConfidenceColor(confidence) as any}
          sx={{ height: getSizeStyles().height, borderRadius: 1 }}
        />
      </Box>
      {showIcon && getConfidenceIcon(confidence)}
      {showPercentage && (
        <Typography
          variant={size === 'small' ? 'caption' : 'body2'}
          color="textSecondary"
          sx={{ fontSize: getSizeStyles().fontSize }}
        >
          {percentage}%
        </Typography>
      )}
    </Box>
  );
};

import React from 'react';
import { Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Chip, IconButton, Tooltip } from '@mui/material';
import { Visibility as ViewIcon, Settings as SettingsIcon } from '@mui/icons-material';
import { ConfidenceIndicator } from './ConfidenceIndicator';

export interface SuggestionTableColumn<T> {
  key: keyof T | string;
  label: string;
  render?: (row: T) => React.ReactNode;
  align?: 'left' | 'center' | 'right';
  width?: string | number;
}

interface SuggestionTableProps<T> {
  data: T[];
  columns: SuggestionTableColumn<T>[];
  onView?: (row: T) => void;
  onOptimize?: (row: T) => void;
  loading?: boolean;
  emptyText?: string;
  className?: string;
}

export function SuggestionTable<T extends { id: string }>({
  data,
  columns,
  onView,
  onOptimize,
  loading = false,
  emptyText = 'Keine Vorschläge gefunden',
  className = ''
}: SuggestionTableProps<T>) {
  return (
    <TableContainer component={Paper} className={className}>
      <Table size="small">
        <TableHead>
          <TableRow>
            {columns.map((col) => (
              <TableCell key={col.key as string} align={col.align || 'left'} style={col.width ? { width: col.width } : {}}>
                {col.label}
              </TableCell>
            ))}
            {(onView || onOptimize) && <TableCell align="center">Aktionen</TableCell>}
          </TableRow>
        </TableHead>
        <TableBody>
          {data.length === 0 && (
            <TableRow>
              <TableCell colSpan={columns.length + ((onView || onOptimize) ? 1 : 0)} align="center">
                {emptyText}
              </TableCell>
            </TableRow>
          )}
          {data.map((row) => (
            <TableRow key={row.id} hover>
              {columns.map((col) => (
                <TableCell key={col.key as string} align={col.align || 'left'}>
                  {col.render ? col.render(row) : (row as any)[col.key]}
                </TableCell>
              ))}
              {(onView || onOptimize) && (
                <TableCell align="center">
                  <div className="flex gap-1 justify-center">
                    {onView && (
                      <Tooltip title="Details anzeigen">
                        <IconButton size="small" onClick={() => onView(row)}>
                          <ViewIcon />
                        </IconButton>
                      </Tooltip>
                    )}
                    {onOptimize && (
                      <Tooltip title="Optimieren">
                        <IconButton size="small" onClick={() => onOptimize(row)}>
                          <SettingsIcon />
                        </IconButton>
                      </Tooltip>
                    )}
                  </div>
                </TableCell>
              )}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Card, Typography, Button, Alert, Box, CircularProgress } from '@mui/material';
import { CameraAlt as CameraIcon, QrCode as QrCodeIcon } from '@mui/icons-material';
import Quagga from 'quagga';

interface BarcodeScannerProps {
  onBarcodeDetected: (barcode: string) => void;
  onError?: (error: string) => void;
  autoStart?: boolean;
  className?: string;
}

interface ScanResult {
  codeResult: {
    code: string;
    format: string;
  };
}

export const BarcodeScanner: React.FC<BarcodeScannerProps> = ({
  onBarcodeDetected,
  onError,
  autoStart = false,
  className = ''
}) => {
  const scannerRef = useRef<HTMLDivElement>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastScannedCode, setLastScannedCode] = useState<string | null>(null);

  // Barcode-Erkennung Callback
  const onDetected = useCallback((result: ScanResult) => {
    const code = result.codeResult.code;
    if (code && code !== lastScannedCode) {
      setLastScannedCode(code);
      onBarcodeDetected(code);

      // Kurze Pause nach erfolgreichem Scan
      setTimeout(() => {
        setLastScannedCode(null);
      }, 2000);
    }
  }, [onBarcodeDetected, lastScannedCode]);

  // Scanner initialisieren
  const initializeScanner = useCallback(async () => {
    if (!scannerRef.current) return;

    try {
      setError(null);
      setIsInitialized(false);

      await Quagga.init({
        inputStream: {
          name: "Live",
          type: "LiveStream",
          target: scannerRef.current,
          constraints: {
            width: { min: 640, ideal: 1280, max: 1920 },
            height: { min: 480, ideal: 720, max: 1080 },
            facingMode: "environment" // Rückkamera bevorzugen
          },
        },
        locator: {
          patchSize: "medium",
          halfSample: true
        },
        numOfWorkers: navigator.hardwareConcurrency || 4,
        frequency: 10,
        decoder: {
          readers: [
            "ean_reader",
            "ean_8_reader",
            "code_128_reader",
            "code_39_reader",
            "upc_reader",
            "upc_e_reader"
          ]
        },
        locate: true
      });

      Quagga.onDetected(onDetected);
      setIsInitialized(true);

      if (autoStart) {
        startScanning();
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Scanner-Initialisierung fehlgeschlagen';
      setError(errorMessage);
      onError?.(errorMessage);
    }
  }, [onDetected, autoStart, onError]);

  // Scanner starten
  const startScanning = useCallback(async () => {
    if (!isInitialized) {
      await initializeScanner();
    }

    try {
      await Quagga.start();
      setIsScanning(true);
      setError(null);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Scanner konnte nicht gestartet werden';
      setError(errorMessage);
      onError?.(errorMessage);
    }
  }, [isInitialized, initializeScanner, onError]);

  // Scanner stoppen
  const stopScanning = useCallback(() => {
    Quagga.stop();
    setIsScanning(false);
  }, []);

  // Komponente aufräumen
  useEffect(() => {
    return () => {
      if (isScanning) {
        Quagga.stop();
      }
    };
  }, [isScanning]);

  // Initialisierung beim Mount
  useEffect(() => {
    if (autoStart) {
      initializeScanner();
    }
  }, [autoStart, initializeScanner]);

  return (
    <Card className={`p-4 ${className}`}>
      <Box className="flex items-center justify-between mb-4">
        <Typography variant="h6" className="flex items-center gap-2">
          <QrCodeIcon />
          Barcode-Scanner
        </Typography>

        <Box className="flex gap-2">
          {!isScanning ? (
            <Button
              variant="contained"
              startIcon={<CameraIcon />}
              onClick={startScanning}
              disabled={!isInitialized && !autoStart}
            >
              Scanner starten
            </Button>
          ) : (
            <Button
              variant="outlined"
              color="secondary"
              onClick={stopScanning}
            >
              Scanner stoppen
            </Button>
          )}
        </Box>
      </Box>

      {error && (
        <Alert severity="error" className="mb-4">
          {error}
        </Alert>
      )}

      {lastScannedCode && (
        <Alert severity="success" className="mb-4">
          Barcode erkannt: <strong>{lastScannedCode}</strong>
        </Alert>
      )}

      <Box className="relative">
        <div
          ref={scannerRef}
          className="w-full h-64 bg-gray-100 rounded-lg overflow-hidden border-2 border-gray-300"
        >
          {!isScanning && (
            <Box className="flex items-center justify-center h-full">
              <Box className="text-center">
                <CameraIcon className="text-4xl text-gray-400 mb-2" />
                <Typography variant="body2" color="textSecondary">
                  Scanner bereit - Klicken Sie auf "Scanner starten"
                </Typography>
              </Box>
            </Box>
          )}
        </div>

        {isScanning && (
          <Box className="absolute inset-0 flex items-center justify-center">
            <CircularProgress size={40} />
          </Box>
        )}
      </Box>

      <Box className="mt-4">
        <Typography variant="body2" color="textSecondary">
          Unterstützte Formate: EAN-13, EAN-8, Code 128, Code 39, UPC
        </Typography>
      </Box>
    </Card>
  );
};

