      label: 'Allgemein',
      icon: <PersonIcon />,
      component: CustomerGeneralTab,
      subTabs: [],
      isEnabled: true,
      isVisible: true,
      order: 1
    },
    {
      id: CRMMainTab.CONTACTS,
      label: 'Kontakte',
      icon: <ContactsIcon />,
      component: CustomerContactsTab,
      subTabs: [],
      isEnabled: true,
      isVisible: true,
      order: 2
    },
    {
      id: CRMMainTab.SALES,
      label: 'Vertrieb',
      icon: <TrendingUpIcon />,
      component: CustomerSalesTab,
      subTabs: [],
      isEnabled: true,
      isVisible: true,
      order: 3
    },
    {
      id: CRMMainTab.ORDERS,
      label: 'Aufträge',
      icon: <ShoppingCartIcon />,
      component: CustomerOrdersTab,
      subTabs: [],
      isEnabled: true,
      isVisible: true,
      order: 4
    },
    {
      id: CRMMainTab.INVOICES,
      label: 'Rechnungen',
      icon: <ReceiptIcon />,
      component: CustomerInvoicesTab,
      subTabs: [],
      isEnabled: true,
