interface CRMReportingAnalyticsProps {
  onReportClick?: (reportType: string, data?: any) => void;
}

interface CustomerData {
  id: string;
  name: string;
  segment: string;
  status: string;
  revenue: number;
  lastOrder: string;
  riskScore: number;
}

interface CommunicationData {
  id: string;
  customer: string;
  type: string;
  subject: string;
  date: string;
  status: string;
  outcome: string;
}

interface OfferData {
  id: string;
  customer: string;
  title: string;
  value: number;
  status: string;
  createdDate: string;
  validUntil: string;
}

interface OrderData {
  id: string;
  customer: string;
  orderNumber: string;
  total: number;
  status: string;
  orderDate: string;
  deliveryDate: string;
}

interface InvoiceData {
  id: string;
  customer: string;
  invoiceNumber: string;
  amount: number;
  status: string;
  issueDate: string;
  dueDate: string;
}

type ReportData = CustomerData | CommunicationData | OfferData | OrderData | InvoiceData;

const CRMReportingAnalytics: React.FC<CRMReportingAnalyticsProps> = ({
  onReportClick
}) => {
  const [selectedReport, setSelectedReport] = useState<string>('customers');
  const [dateFrom, setDateFrom] = useState<Date | null>(null);
  const [dateTo, setDateTo] = useState<Date | null>(null);
  const [filters, setFilters] = useState<any>({});
  const [isExportDialogOpen, setIsExportDialogOpen] = useState(false);
  const [exportFormat, setExportFormat] = useState<string>('excel');

  // Fetch CRM analytics data
  const { data: analytics, isLoading, error, refetch } = useQuery({
    queryKey: ['crm-analytics', selectedReport, dateFrom, dateTo, filters],
    queryFn: () => Promise.resolve({ customers: [], revenue: 0, orders: 0 }), // Mock data
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  const handleReportChange = (reportType: string) => {
    setSelectedReport(reportType);
  };

  const handleFilterChange = (filterName: string, value: any) => {
    setFilters(prev => ({
      ...prev,
      [filterName]: value
    }));
  };

  const handleExport = () => {
    setIsExportDialogOpen(true);
  };

  const handleExportConfirm = async () => {
    try {
      const response = await fetch('/api/crm/reports/export', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('authToken')}`
        },
        body: JSON.stringify({
          reportType: selectedReport,
          format: exportFormat,
          filters: filters,
          dateRange: {
            start: filters.startDate,
            end: filters.endDate
          }
        })
      });

      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `crm-report-${selectedReport}-${new Date().toISOString().split('T')[0]}.${exportFormat}`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);

        console.log('Report exported successfully in format:', exportFormat);
      } else {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
    } catch (err) {
      console.error('Error exporting report:', err);
      alert('Fehler beim Exportieren des Reports');
    } finally {
      setIsExportDialogOpen(false);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('de-DE', {
      style: 'currency',
      currency: 'EUR'
    }).format(amount);
  };

  const formatNumber = (num: number) => {
    return new Intl.NumberFormat('de-DE').format(num);
  };

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString('de-DE');
  };

  const getReportData = () => {
    // Mock data for different report types
    const mockData = {
      customers: [
        {
          id: '1',
          name: 'Musterfirma GmbH',
          segment: 'Premium',
          status: 'Aktiv',
          revenue: 150000,
          lastOrder: '2024-01-20',
          riskScore: 2
        },
        {
          id: '2',
          name: 'Beispiel AG',
          segment: 'Standard',
          status: 'Aktiv',
          revenue: 75000,
          lastOrder: '2024-01-18',
          riskScore: 4
        }
      ],
      communications: [
        {
          id: '1',
          customer: 'Musterfirma GmbH',
          type: 'WhatsApp',
          subject: 'Bestellbestätigung',
          date: '2024-01-20',
          status: 'Delivered',
          outcome: 'Positive'
        },
        {
          id: '2',
          customer: 'Beispiel AG',
          type: 'Email',
          subject: 'Angebot',
          date: '2024-01-19',
          status: 'Sent',
          outcome: 'Neutral'
        }
      ],
      offers: [
        {
          id: '1',
          customer: 'Musterfirma GmbH',
          number: 'OFF-2024-001',
          title: 'Maschinenausstattung',
          amount: 50000,
          status: 'Draft',
          validUntil: '2024-02-20'
        }
      ],
      orders: [
        {
          id: '1',
          customer: 'Musterfirma GmbH',
          number: 'ORD-2024-001',
          title: 'Maschinenausstattung',
          amount: 50000,
          status: 'Confirmed',
          orderDate: '2024-01-20',
          deliveryDate: '2024-02-15'
        }
      ],
      invoices: [
        {
          id: '1',
          customer: 'Musterfirma GmbH',
          number: 'INV-2024-001',
          title: 'Maschinenausstattung',
          amount: 50000,
          status: 'Paid',
          invoiceDate: '2024-02-01',
          dueDate: '2024-03-01'
        }
      ]
    };

    return mockData[selectedReport as keyof typeof mockData] || [];
  };

  const getReportColumns = () => {
    const columns = {
      customers: [
        { field: 'name', header: 'Kundenname' },
        { field: 'segment', header: 'Segment' },
        { field: 'status', header: 'Status' },
        { field: 'revenue', header: 'Umsatz' },
        { field: 'lastOrder', header: 'Letzter Auftrag' },
        { field: 'riskScore', header: 'Risikobewertung' }
      ],
      communications: [
        { field: 'customer', header: 'Kunde' },
        { field: 'type', header: 'Typ' },
        { field: 'subject', header: 'Betreff' },
        { field: 'date', header: 'Datum' },
        { field: 'status', header: 'Status' },
        { field: 'outcome', header: 'Ergebnis' }
      ],
      offers: [
        { field: 'customer', header: 'Kunde' },
        { field: 'number', header: 'Angebotsnummer' },
        { field: 'title', header: 'Titel' },
        { field: 'amount', header: 'Betrag' },
        { field: 'status', header: 'Status' },
        { field: 'validUntil', header: 'Gültig bis' }
      ],
      orders: [
        { field: 'customer', header: 'Kunde' },
        { field: 'number', header: 'Auftragsnummer' },
        { field: 'title', header: 'Titel' },
        { field: 'amount', header: 'Betrag' },
        { field: 'status', header: 'Status' },
        { field: 'orderDate', header: 'Auftragsdatum' },
        { field: 'deliveryDate', header: 'Lieferdatum' }
      ],
      invoices: [
        { field: 'customer', header: 'Kunde' },
        { field: 'number', header: 'Rechnungsnummer' },
        { field: 'title', header: 'Titel' },
        { field: 'amount', header: 'Betrag' },
        { field: 'status', header: 'Status' },
        { field: 'invoiceDate', header: 'Rechnungsdatum' },
        { field: 'dueDate', header: 'Fälligkeitsdatum' }
      ]
    };

    return columns[selectedReport as keyof typeof columns] || [];
  };

  const renderTableCell = (row: any, column: any) => {
    const value = row[column.field];

    switch (column.field) {
      case 'revenue':
      case 'amount':
        return formatCurrency(value);
      case 'lastOrder':
      case 'date':
      case 'validUntil':
      case 'orderDate':
      case 'deliveryDate':
      case 'invoiceDate':
      case 'dueDate':
        return formatDate(value);
      case 'segment':
        return (
          <Chip
            label={value}
            color={value === 'Premium' ? 'primary' : value === 'Standard' ? 'success' : 'default'}
            size="small"
          />
        );
      case 'status':
        return (
          <Chip
            label={value}
            color={value === 'Aktiv' || value === 'Confirmed' || value === 'Paid' ? 'success' : 
                   value === 'Draft' ? 'default' : 'warning'}
            size="small"
          />
        );
      case 'type':
        return (
          <Chip
            label={value}
            color={value === 'WhatsApp' ? 'success' : value === 'Email' ? 'primary' : 'default'}
            size="small"
          />
        );
      case 'outcome':
        return (
          <Chip
            label={value}
            color={value === 'Positive' ? 'success' : value === 'Negative' ? 'error' : 'default'}
            size="small"
          />
        );
      default:
        return value;
    }
  };

  if (isLoading) {
    return (
      <Box className="flex justify-center items-center h-64">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box className="p-4">
        <Alert severity="error">
          Fehler beim Laden der Reporting-Daten: {error.message}
        </Alert>
      </Box>
    );
  }

  const reportData = getReportData();
  const reportColumns = getReportColumns();

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={de}>
      <Box className="p-6 space-y-6">
        {/* Header */}
        <Box className="flex justify-between items-center">
          <Typography variant="h4" className="text-gray-800">
            Reporting & Analytics
          </Typography>
          <Box className="flex gap-2">
            <Button
              variant="outlined"
              startIcon={<RefreshIcon />}
              onClick={() => refetch()}
            >
              Aktualisieren
            </Button>
            <Button
              variant="contained"
              startIcon={<DownloadIcon />}
              onClick={handleExport}
            >
              Exportieren
            </Button>
          </Box>
        </Box>

        {/* Report Type Selection */}
        <Card>
          <CardContent>
            <Typography variant="h6" className="mb-4">
              Berichtstyp auswählen
            </Typography>
