            {selectedMessage && (
              <Card variant="outlined">
                <CardContent className="p-3">
                  <Typography variant="caption" className="text-gray-500">
                    Original Nachricht:
                  </Typography>
                  <Typography variant="body2" className="mt-1">
                    {selectedMessage.content}
                  </Typography>
