interface EInvoicingListProps {
  // Props für die e-Invoicing-Liste
}

const EInvoicingList: React.FC<EInvoicingListProps> = () => {
  const [invoices, setInvoices] = useState<InvoiceSummary[]>([]);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState<InvoiceFilter>({
    startDate: '',
    endDate: ''
  });
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 10,
    total: 0,
  });

  useEffect(() => {
    fetchInvoices();
  }, [filter, pagination.current, pagination.pageSize]);

  const fetchInvoices = async () => {
    setLoading(true);
    try {
      const data = await EInvoicingApi.getInvoices(filter);
      setInvoices(data);
      setPagination(prev => ({ ...prev, total: data.length }));
    } catch (error) {
      console.error('Fehler beim Laden der e-Rechnungen:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = async (invoiceId: string) => {
    try {
      const blob = await EInvoicingApi.downloadInvoice(invoiceId);
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `invoice-${invoiceId}.pdf`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      console.error('Fehler beim Herunterladen:', error);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PAID': return 'green';
      case 'PENDING': return 'orange';
      case 'OVERDUE': return 'red';
      case 'DRAFT': return 'blue';
      default: return 'default';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'PAID': return 'Bezahlt';
      case 'PENDING': return 'Ausstehend';
      case 'OVERDUE': return 'Überfällig';
      case 'DRAFT': return 'Entwurf';
      default: return status;
    }
  };

  const columns = [
    {
      title: 'Rechnungsnummer',
      dataIndex: 'invoiceNumber',
      key: 'invoiceNumber',
      fixed: 'left' as const,
      width: 150,
      render: (text: string) => <strong>{text}</strong>,
    },
    {
      title: 'Kunde',
      dataIndex: 'customerName',
      key: 'customerName',
      width: 200,
    },
    {
      title: 'Betrag',
      dataIndex: 'amount',
      key: 'amount',
      width: 120,
      render: (amount: number, record: InvoiceSummary) => 
        formatCurrency(amount, record.currency),
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      width: 120,
      render: (status: string) => (
        <Tag color={getStatusColor(status)}>
          {getStatusLabel(status)}
        </Tag>
      ),
    },
    {
      title: 'Erstellt',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 120,
      render: (date: string) => formatDate(date),
    },
    {
      title: 'Aktionen',
      key: 'actions',
      fixed: 'right' as const,
      width: 150,
      render: (text: string, record: InvoiceSummary) => (
        <Space size="small">
          <Button
            type="link"
            icon={<EyeOutlined />}
            onClick={() => handleView(record.invoiceId)}
            title="Anzeigen"
          />
          <Button
            type="link"
            icon={<DownloadOutlined />}
            onClick={() => handleDownload(record.invoiceId)}
            title="Herunterladen"
          />
          <Button
            type="link"
            danger
            icon={<DeleteOutlined />}
            onClick={() => handleDelete(record.invoiceId)}
            title="Löschen"
          />
        </Space>
      ),
    },
  ];

