  const { control, formState: { errors }, watch, setValue } = useFormContext();
  const [showPassword, setShowPassword] = React.useState(false);
  const [showClear, setShowClear] = React.useState(false);

  const value = watch(name);

  React.useEffect(() => {
    setShowClear(!!value && showClearButton);
  }, [value, showClearButton]);

  const handleClear = () => {
    setValue(name, '');
  };

  const getInputProps = () => {
    const props: any = {};

    if (startAdornment) {
      props.startAdornment = startAdornment;
    }

    if (endAdornment) {
      props.endAdornment = endAdornment;
    }

    if (type === 'password') {
      props.endAdornment = (
        <InputAdornment position="end">
          <IconButton
            onClick={() => setShowPassword(!showPassword)}
            edge="end"
          >
            {showPassword ? <VisibilityOffIcon /> : <VisibilityIcon />}
          </IconButton>
        </InputAdornment>
      );
    }

    if (showClear && value) {
      props.endAdornment = (
        <InputAdornment position="end">
          <IconButton onClick={handleClear} edge="end">
            <ClearIcon />
          </IconButton>
        </InputAdornment>
      );
    }

    return props;
  };

  return (
    <Controller
      name={name}
      control={control}
      rules={{
        required: required ? `${label} ist erforderlich` : false,
        minLength: minLength ? { value: minLength, message: `Mindestens ${minLength} Zeichen` } : undefined,
        maxLength: maxLength ? { value: maxLength, message: `Maximal ${maxLength} Zeichen` } : undefined,
        pattern: pattern ? { value: pattern, message: `Ungültiges Format` } : undefined
      }}
      render={({ field }) => (
        <Box sx={{ position: 'relative' }}>
          <TextField
            {...field}
            label={label}
            type={type === 'password' ? (showPassword ? 'text' : 'password') : type}
            required={required}
            disabled={disabled}
            placeholder={placeholder}
            multiline={multiline}
            rows={rows}
            fullWidth
            variant="outlined"
            error={!!errors[name]}
            helperText={errors[name]?.message?.toString() || helperText}
            InputProps={getInputProps()}
            sx={{
              '& .MuiOutlinedInput-root': {
                borderRadius: 2,
                '&:hover fieldset': {
                  borderColor: 'primary.main',
                },
                '&.Mui-focused fieldset': {
                  borderColor: 'primary.main',
                },
              },
            }}
          />
          {showInfoTooltip && (
            <Tooltip title={infoText || `Informationen zu ${label}`} placement="top">
              <IconButton
                size="small"
                sx={{
                  position: 'absolute',
                  right: -40,
                  top: '50%',
                  transform: 'translateY(-50%)',
                  color: 'text.secondary'
                }}
              >
                <InfoIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          )}
        </Box>
      )}
    />
  );
};

export interface StandardSelectFieldProps {
  name: string;
  label: string;
  options: Array<{ value: string | number; label: string; disabled?: boolean }>;
  required?: boolean;
  disabled?: boolean;
  multiple?: boolean;
  helperText?: string;
  showInfoTooltip?: boolean;
  infoText?: string;
}

/**
 * Standardisiertes Select-Feld für alle Formulare
 */
export const StandardSelectField: React.FC<StandardSelectFieldProps> = ({
  name,
  label,
  options,
  required = false,
  disabled = false,
  multiple = false,
  helperText,
  showInfoTooltip = false,
  infoText
}) => {
  const { control, formState: { errors } } = useFormContext();

  return (
    <Controller
      name={name}
      control={control}
      defaultValue={multiple ? [] : ''}
      rules={{
        required: required ? `${label} ist erforderlich` : false
      }}
      render={({ field }) => (
        <Box sx={{ position: 'relative' }}>
          <FormControl fullWidth error={!!errors[name]} disabled={disabled}>
            {/** Verbinde Label und Select per IDs für korrekte ARIA-Assoziation */}
            <InputLabel id={`${name}-label`} required={required}>{label}</InputLabel>
            <Select
              {...field}
              labelId={`${name}-label`}
              id={`${name}-select`}
              label={label}
              multiple={multiple}
              value={multiple ? (Array.isArray(field.value) ? field.value : (field.value ? [field.value] : [])) : (field.value ?? '')}
              onChange={(event) => {
                const value = (event.target as HTMLInputElement).value as any;
                field.onChange(value);
              }}
              sx={{
                borderRadius: 2,
                '&:hover .MuiOutlinedInput-notchedOutline': {
                  borderColor: 'primary.main',
                },
                '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                  borderColor: 'primary.main',
                },
              }}
            >
              {options.map((option) => (
                <MenuItem
                  key={option.value}
                  value={option.value}
                  disabled={option.disabled}
                >
                  {option.label}
                </MenuItem>
              ))}
            </Select>
            {(errors[name]?.message || helperText) && (
              <FormHelperText>{errors[name]?.message?.toString() || helperText}</FormHelperText>
            )}
          </FormControl>
          {showInfoTooltip && (
            <Tooltip title={infoText || `Informationen zu ${label}`} placement="top">
              <IconButton
                size="small"
                sx={{
                  position: 'absolute',
                  right: -40,
                  top: '50%',
                  transform: 'translateY(-50%)',
                  color: 'text.secondary'
                }}
              >
                <InfoIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          )}
        </Box>
      )}
    />
  );
};

