    <Card className="max-w-2xl mx-auto shadow-lg">
      <CardHeader>
        <Typography variant="h5" className="flex items-center">
          <AssignmentIcon className="mr-2" />
          {initialData ? 'Rechnung bearbeiten' : 'Neue Rechnung erstellen'}
