  Divider,
  Paper,
  Fade,
  Zoom
} from '@mui/material';
import {
  Save as SaveIcon,
  Cancel as CancelIcon,
  KeyboardArrowRight as ArrowIcon,
  QrCodeScanner as BarcodeIcon,
  AutoFixHigh as AutoCompleteIcon,
  ErrorOutline as ErrorIcon,
