interface StockOpnameItem {
  id: string;
  product_id: string;
  product_name: string;
  product_code: string;
  expected_quantity: number;
  actual_quantity: number;
  difference: number;
  unit: string;
  notes?: string;
}

interface StockOpname {
  id: string;
  number: string;
  date: string;
  status: 'offen' | 'in_bearbeitung' | 'abgeschlossen' | 'storniert';
  responsible_person: string;
  total_items: number;
  completed_items: number;
  created_at: string;
}

interface StockOpnameInterfaceProps {
  className?: string;
}

export const StockOpnameInterface: React.FC<StockOpnameInterfaceProps> = ({
  className = ''
}) => {
  const [stockOpnames, setStockOpnames] = useState<StockOpname[]>([]);
  const [currentOpname, setCurrentOpname] = useState<StockOpname | null>(null);
  const [opnameItems, setOpnameItems] = useState<StockOpnameItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // Dialog States
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editItemDialogOpen, setEditItemDialogOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState<StockOpnameItem | null>(null);

  // Form States
  const [newOpnameData, setNewOpnameData] = useState({
    responsible_person: '',
    date: new Date().toISOString().split('T')[0]
  });

  const [editItemData, setEditItemData] = useState({
    actual_quantity: 0,
    notes: ''
  });

  // Stock Opnames laden
  const loadStockOpnames = useCallback(async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/stock-opname');
      if (response.ok) {
        const data = await response.json();
        setStockOpnames(data.stock_opnames || []);
      } else {
        throw new Error('Fehler beim Laden der Inventuren');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unbekannter Fehler');
    } finally {
      setLoading(false);
    }
  }, []);

  // Neue Inventur erstellen
  const createStockOpname = useCallback(async () => {
    try {
      const response = await fetch('/api/stock-opname', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newOpnameData)
      });

      if (response.ok) {
        const data = await response.json();
        setSuccess('Inventur erfolgreich erstellt');
        setCreateDialogOpen(false);
        setNewOpnameData({ responsible_person: '', date: new Date().toISOString().split('T')[0] });
        loadStockOpnames();
      } else {
        throw new Error('Fehler beim Erstellen der Inventur');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unbekannter Fehler');
    }
  }, [newOpnameData, loadStockOpnames]);

  // Inventur öffnen
  const openStockOpname = useCallback(async (opname: StockOpname) => {
    setLoading(true);
    try {
      const response = await fetch(`/api/stock-opname/${opname.id}/items`);
      if (response.ok) {
        const data = await response.json();
        setOpnameItems(data.items || []);
        setCurrentOpname(opname);
      } else {
        throw new Error('Fehler beim Laden der Inventur-Details');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unbekannter Fehler');
    } finally {
      setLoading(false);
    }
  }, []);

  // Barcode-Scan Handler
  const handleBarcodeDetected = useCallback(async (barcode: string) => {
    // Produkt über Barcode suchen und zur Inventur hinzufügen
    console.log('Barcode erkannt:', barcode);

    if (!currentOpname) {
      setError('Keine aktive Inventur ausgewählt');
      return;
    }

    try {
      const response = await fetch(`/api/products/barcode/${barcode}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('authToken')}`
        }
      });

      if (response.ok) {
        const product = await response.json();

        // Add product to stock opname
        const addResponse = await fetch(`/api/stock-opname/${currentOpname.id}/items`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${localStorage.getItem('authToken')}`
          },
          body: JSON.stringify({
            product_id: product.id,
            expected_quantity: product.quantity || 0
          })
        });

        if (addResponse.ok) {
          setSuccess(`Produkt "${product.name}" zur Inventur hinzugefügt`);
          // Reload items
          if (currentOpname) {
            openStockOpname(currentOpname);
          }
        } else {
          throw new Error('Fehler beim Hinzufügen des Produkts zur Inventur');
        }
      } else {
        setError('Produkt nicht gefunden');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Fehler beim Hinzufügen des Produkts');
    }
  }, [currentOpname, openStockOpname]);

  // Item bearbeiten
  const editItem = useCallback((item: StockOpnameItem) => {
    setSelectedItem(item);
    setEditItemData({
      actual_quantity: item.actual_quantity,
      notes: item.notes || ''
    });
    setEditItemDialogOpen(true);
  }, []);

  // Item speichern
  const saveItem = useCallback(async () => {
    if (!selectedItem) return;

    try {
      const response = await fetch(`/api/stock-opname/items/${selectedItem.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(editItemData)
      });

      if (response.ok) {
        setSuccess('Artikel erfolgreich aktualisiert');
        setEditItemDialogOpen(false);
        setSelectedItem(null);
        // Items neu laden
        if (currentOpname) {
          openStockOpname(currentOpname);
        }
      } else {
        throw new Error('Fehler beim Aktualisieren des Artikels');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unbekannter Fehler');
    }
  }, [selectedItem, editItemData, currentOpname, openStockOpname]);

  // Inventur abschließen
  const closeStockOpname = useCallback(async () => {
    if (!currentOpname) return;

    try {
      const response = await fetch(`/api/stock-opname/${currentOpname.id}/close`, {
        method: 'POST'
      });

      if (response.ok) {
        setSuccess('Inventur erfolgreich abgeschlossen');
        setCurrentOpname(null);
        setOpnameItems([]);
        loadStockOpnames();
      } else {
        throw new Error('Fehler beim Abschließen der Inventur');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unbekannter Fehler');
    }
  }, [currentOpname, loadStockOpnames]);

  // Status-Farbe
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'offen': return 'default';
      case 'in_bearbeitung': return 'warning';
      case 'abgeschlossen': return 'success';
      case 'storniert': return 'error';
      default: return 'default';
    }
  };

  // Status-Text
  const getStatusText = (status: string) => {
    switch (status) {
      case 'offen': return 'Offen';
      case 'in_bearbeitung': return 'In Bearbeitung';
      case 'abgeschlossen': return 'Abgeschlossen';
      case 'storniert': return 'Storniert';
      default: return status;
    }
  };

  // Progress berechnen
  const getProgress = (opname: StockOpname) => {
    return opname.total_items > 0 ? (opname.completed_items / opname.total_items) * 100 : 0;
  };

  useEffect(() => {
    loadStockOpnames();
  }, [loadStockOpnames]);

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <Box className="flex items-center justify-between">
        <Typography variant="h4" className="flex items-center gap-2">
          <InventoryIcon />
          Inventur-Verwaltung
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setCreateDialogOpen(true)}
        >
          Neue Inventur
        </Button>
      </Box>

      {/* Alerts */}
      {error && (
        <Alert severity="error" onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" onClose={() => setSuccess(null)}>
          {success}
        </Alert>
      )}

      {/* Inventur-Liste */}
      {!currentOpname && (
        <Card className="p-4">
          <Typography variant="h6" className="mb-4">
            Inventuren
          </Typography>

          {loading ? (
            <Box className="flex justify-center p-8">
              <CircularProgress />
            </Box>
          ) : (
            <TableContainer component={Paper}>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Nummer</TableCell>
                    <TableCell>Datum</TableCell>
                    <TableCell>Verantwortlicher</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Fortschritt</TableCell>
                    <TableCell>Aktionen</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {stockOpnames.map((opname) => (
                    <TableRow key={opname.id} hover>
                      <TableCell>{opname.number}</TableCell>
                      <TableCell>{new Date(opname.date).toLocaleDateString('de-DE')}</TableCell>
                      <TableCell>{opname.responsible_person}</TableCell>
                      <TableCell>
                        <Chip
                          label={getStatusText(opname.status)}
                          color={getStatusColor(opname.status)}
                          size="small"
                        />
                      </TableCell>
                      <TableCell>
                        <Box className="flex items-center gap-2">
                          <Box className="w-16 bg-gray-200 rounded-full h-2">
                            <Box
                              className="bg-blue-600 h-2 rounded-full"
                              style={{ width: `${getProgress(opname)}%` }}
                            />
                          </Box>
                          <Typography variant="body2">
                            {opname.completed_items}/{opname.total_items}
                          </Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Button
                          size="small"
                          onClick={() => openStockOpname(opname)}
                          disabled={opname.status === 'abgeschlossen'}
                        >
                          Öffnen
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Card>
      )}

      {/* Inventur-Details */}
      {currentOpname && (
        <div className="space-y-4">
          {/* Header */}
          <Card className="p-4">
            <Box className="flex items-center justify-between mb-4">
              <Box>
                <Typography variant="h6">
                  Inventur: {currentOpname.number}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  {new Date(currentOpname.date).toLocaleDateString('de-DE')} - {currentOpname.responsible_person}
                </Typography>
              </Box>
              <Box className="flex gap-2">
                <Button
                  variant="outlined"
                  onClick={() => {
                    setCurrentOpname(null);
                    setOpnameItems([]);
                  }}
                >
                  Zurück
                </Button>
                <Button
                  variant="contained"
                  color="success"
                  startIcon={<CheckCircleIcon />}
                  onClick={closeStockOpname}
                  disabled={currentOpname.status === 'abgeschlossen'}
                >
                  Inventur abschließen
                </Button>
              </Box>
            </Box>

            <Chip
              label={getStatusText(currentOpname.status)}
              color={getStatusColor(currentOpname.status)}
            />
          </Card>

          {/* Barcode-Scanner */}
          <BarcodeScanner
            onBarcodeDetected={handleBarcodeDetected}
            onError={setError}
            className="mb-4"
          />

          {/* Artikel-Liste */}
          <Card className="p-4">
            <Typography variant="h6" className="mb-4">
              Inventur-Artikel
            </Typography>

            <TableContainer component={Paper}>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Produkt</TableCell>
                    <TableCell>Code</TableCell>
                    <TableCell align="right">Erwartet</TableCell>
                    <TableCell align="right">Tatsächlich</TableCell>
                    <TableCell align="right">Differenz</TableCell>
                    <TableCell>Notizen</TableCell>
                    <TableCell>Aktionen</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {opnameItems.map((item) => (
                    <TableRow key={item.id} hover>
                      <TableCell>{item.product_name}</TableCell>
                      <TableCell>{item.product_code}</TableCell>
                      <TableCell align="right">{item.expected_quantity} {item.unit}</TableCell>
                      <TableCell align="right">
                        <span className={item.actual_quantity !== item.expected_quantity ? 'text-red-600 font-semibold' : ''}>
                          {item.actual_quantity} {item.unit}
                        </span>
                      </TableCell>
                      <TableCell align="right">
                        <Chip
                          label={`${item.difference > 0 ? '+' : ''}${item.difference}`}
                          color={item.difference === 0 ? 'success' : 'warning'}
                          size="small"
                        />
                      </TableCell>
                      <TableCell>
                        {item.notes && (
                          <Tooltip title={item.notes}>
                            <WarningIcon color="warning" fontSize="small" />
                          </Tooltip>
                        )}
                      </TableCell>
                      <TableCell>
                        <IconButton
                          size="small"
                          onClick={() => editItem(item)}
                        >
                          <EditIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Card>
        </div>
      )}

      {/* Neue Inventur Dialog */}
      <Dialog open={createDialogOpen} onClose={() => setCreateDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Neue Inventur erstellen</DialogTitle>
        <DialogContent>
          <Box className="space-y-4 pt-2">
            <TextField
              label="Verantwortlicher"
              fullWidth
              value={newOpnameData.responsible_person}
              onChange={(e) => setNewOpnameData(prev => ({ ...prev, responsible_person: e.target.value }))}
            />
            <TextField
              label="Datum"
              type="date"
              fullWidth
              value={newOpnameData.date}
              onChange={(e) => setNewOpnameData(prev => ({ ...prev, date: e.target.value }))}
              InputLabelProps={{ shrink: true }}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateDialogOpen(false)}>
            Abbrechen
          </Button>
          <Button onClick={createStockOpname} variant="contained">
            Erstellen
          </Button>
        </DialogActions>
      </Dialog>

      {/* Artikel bearbeiten Dialog */}
      <Dialog open={editItemDialogOpen} onClose={() => setEditItemDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Artikel bearbeiten</DialogTitle>
        <DialogContent>
          {selectedItem && (
            <Box className="space-y-4 pt-2">
              <Typography variant="subtitle1">
                {selectedItem.product_name} ({selectedItem.product_code})
              </Typography>
              <TextField
                label="Tatsächliche Menge"
                type="number"
                fullWidth
                value={editItemData.actual_quantity}
                onChange={(e) => setEditItemData(prev => ({ ...prev, actual_quantity: Number(e.target.value) }))}
              />
              <TextField
                label="Notizen"
                multiline
                rows={3}
                fullWidth
                value={editItemData.notes}
                onChange={(e) => setEditItemData(prev => ({ ...prev, notes: e.target.value }))}
              />
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditItemDialogOpen(false)}>
            Abbrechen
          </Button>
          <Button onClick={saveItem} variant="contained">
            Speichern
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  Card, 
  CardContent, 
  Typography, 
  TextField, 
  FormControl, 
  InputLabel, 
  Select, 
  MenuItem, 
  Checkbox, 
  FormControlLabel, 
  Button, 
  Box, 
  Chip, 
  Alert,
  CircularProgress,
  Divider
} from '../../utils/muiImports';
import { messagingService } from '../../services/MessagingService';
import type { 
  NachrichtEntwurf, 
  EmpfaengerGruppe, 
  KINachrichtenVorschlag,
  NachrichtenFormData,
  NachrichtenFormErrors
} from '../../types/messaging';

interface NachrichtenFormularProps {
  onMessageSent?: (message: any) => void;
  initialData?: Partial<NachrichtEntwurf>;
  showKIVorschlaege?: boolean;
}

export const NachrichtenFormular: React.FC<NachrichtenFormularProps> = ({
  onMessageSent,
  initialData,
  showKIVorschlaege = true
}) => {
  const [formData, setFormData] = useState<NachrichtenFormData>({
    empfaengerGruppe: initialData?.empfaengerGruppe || 'allgemein',
    betreff: initialData?.betreff || '',
    inhalt: initialData?.inhalt || '',
    leseBestaetigungErforderlich: initialData?.leseBestaetigungErforderlich || false,
    archivierungErzwingen: initialData?.archivierungErzwingen || false,
    autoProtokollAnhaengen: initialData?.autoProtokollAnhaengen || false,
    prioritaet: 'normal',
    kategorie: 'allgemein',
    tags: []
  });

  const [errors, setErrors] = useState<NachrichtenFormErrors>({});
  const [loading, setLoading] = useState(false);
  const [kiVorschlaege, setKiVorschlaege] = useState<KINachrichtenVorschlag[]>([]);
  const [showVorschlaege, setShowVorschlaege] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string>('');

  // Empfängergruppen-Optionen
  const empfaengerGruppen: Array<{ value: EmpfaengerGruppe; label: string; description: string }> = [
    { value: 'allgemein', label: 'Allgemein', description: 'Alle Mitarbeiter' },
    { value: 'ao', label: 'AO', description: 'Auftragsorganisation' },
    { value: 'cmk', label: 'CMK', description: 'Controlling & Management' },
    { value: 'cim', label: 'CIM', description: 'Computer Integrated Manufacturing' },
    { value: 'neuroflow', label: 'NeuroFlow', description: 'KI-gestützte Prozesse' },
    { value: 'streckengeschaeft', label: 'Streckengeschäft', description: 'Lieferanten & Bestellungen' },
    { value: 'pos', label: 'POS', description: 'Point of Sale System' },
    { value: 'e-invoicing', label: 'E-Invoicing', description: 'Elektronische Rechnungen' },
    { value: 'crm', label: 'CRM', description: 'Kundenbeziehungsmanagement' },
    { value: 'admin', label: 'Administration', description: 'Systemadministratoren' },
    { value: 'ki-agenten', label: 'KI-Agenten', description: 'Automatisierte Systeme' }
  ];

  // Prioritäts-Optionen
  const prioritaeten = [
    { value: 'niedrig', label: 'Niedrig', color: 'success' },
    { value: 'normal', label: 'Normal', color: 'primary' },
    { value: 'hoch', label: 'Hoch', color: 'warning' },
    { value: 'kritisch', label: 'Kritisch', color: 'error' }
  ];

  // Kategorie-Optionen
  const kategorien = [
    { value: 'allgemein', label: 'Allgemein' },
    { value: 'bestellung', label: 'Bestellung' },
    { value: 'lieferung', label: 'Lieferung' },
    { value: 'rechnung', label: 'Rechnung' },
    { value: 'warnung', label: 'Warnung' },
    { value: 'protokoll', label: 'Protokoll' },
    { value: 'ki-nachricht', label: 'KI-Nachricht' },
    { value: 'system', label: 'System' }
  ];

  useEffect(() => {
    if (showKIVorschlaege) {
      loadKIVorschlaege();
    }
  }, [showKIVorschlaege]);

  const loadKIVorschlaege = async () => {
    try {
      const vorschlaege = await messagingService.generateKINachrichtenVorschlaege();
      setKiVorschlaege(vorschlaege);
    } catch (error) {
      console.error('Fehler beim Laden der KI-Vorschläge:', error);
    }
  };

  const validateForm = (): boolean => {
    const newErrors: NachrichtenFormErrors = {};

    if (!formData.betreff.trim()) {
      newErrors.betreff = 'Betreff ist erforderlich';
    }

    if (!formData.inhalt.trim()) {
      newErrors.inhalt = 'Nachrichteninhalt ist erforderlich';
    }

    if (formData.inhalt.length < 10) {
      newErrors.inhalt = 'Nachricht muss mindestens 10 Zeichen lang sein';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setLoading(true);
    setSuccessMessage('');

    try {
      const nachricht: NachrichtEntwurf = {
        empfaengerGruppe: formData.empfaengerGruppe,
        betreff: formData.betreff,
        inhalt: formData.inhalt,
        leseBestaetigungErforderlich: formData.leseBestaetigungErforderlich,
        archivierungErzwingen: formData.archivierungErzwingen,
        autoProtokollAnhaengen: formData.autoProtokollAnhaengen,
        kiGeneriert: false,
        status: 'entwurf'
      };

      const gesendeteNachricht = await messagingService.createMessage(nachricht);

      setSuccessMessage('Nachricht erfolgreich gesendet!');

      // Formular zurücksetzen
      setFormData({
        empfaengerGruppe: 'allgemein',
        betreff: '',
        inhalt: '',
        leseBestaetigungErforderlich: false,
        archivierungErzwingen: false,
        autoProtokollAnhaengen: false,
        prioritaet: 'normal',
        kategorie: 'allgemein',
        tags: []
      });

      if (onMessageSent) {
        onMessageSent(gesendeteNachricht);
      }

    } catch (error) {
      console.error('Fehler beim Senden der Nachricht:', error);
      setErrors({ betreff: 'Fehler beim Senden der Nachricht' });
    } finally {
      setLoading(false);
    }
  };

  const handleKIVorschlag = (vorschlag: KINachrichtenVorschlag) => {
    setFormData(prev => ({
      ...prev,
      betreff: vorschlag.betreff,
      inhalt: vorschlag.inhalt,
      empfaengerGruppe: vorschlag.empfaengerGruppe,
      prioritaet: vorschlag.prioritaet
    }));
    setShowVorschlaege(false);
  };

  const handleTagesprotokollEinfuegen = async () => {
    try {
      setLoading(true);
      const protokoll = await messagingService.generateTagesprotokoll();
      setFormData(prev => ({
        ...prev,
        inhalt: prev.inhalt + `\n\n--- Tagesprotokoll ---\n${protokoll.zusammenfassung}\n\nBestellungen: ${protokoll.bestellungen}\nLieferungen: ${protokoll.lieferungen}\nRechnungen: ${protokoll.rechnungen}`
      }));
    } catch (error) {
      console.error('Fehler beim Einfügen des Tagesprotokolls:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card className="max-w-4xl mx-auto">
      <CardContent className="p-6">
        <Typography variant="h5" gutterBottom className="text-gray-800 mb-6">
          ✉️ Nachricht versenden
        </Typography>

        {successMessage && (
          <Alert severity="success" className="mb-4">
            {successMessage}
          </Alert>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Empfängergruppe */}
          <FormControl fullWidth error={!!errors.empfaengerGruppe}>
            <InputLabel>Empfängergruppe</InputLabel>
            <Select
              value={formData.empfaengerGruppe}
              onChange={(e) => setFormData(prev => ({ 
                ...prev, 
                empfaengerGruppe: e.target.value as EmpfaengerGruppe 
              }))}
              label="Empfängergruppe"
            >
              {empfaengerGruppen.map(gruppe => (
                <MenuItem key={gruppe.value} value={gruppe.value}>
                  <Box>
                    <Typography variant="body1">{gruppe.label}</Typography>
                    <Typography variant="caption" color="text.secondary">
                      {gruppe.description}
                    </Typography>
                  </Box>
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {/* Betreff */}
          <TextField
            fullWidth
            label="Betreff"
            value={formData.betreff}
            onChange={(e) => setFormData(prev => ({ ...prev, betreff: e.target.value }))}
            error={!!errors.betreff}
            helperText={errors.betreff}
            placeholder="z.B. Tagesprotokoll vom 25.07.2025"
          />

          {/* Nachrichteninhalt */}
          <TextField
            fullWidth
            label="Nachricht"
            value={formData.inhalt}
            onChange={(e) => setFormData(prev => ({ ...prev, inhalt: e.target.value }))}
            error={!!errors.inhalt}
            helperText={errors.inhalt}
            multiline
            rows={6}
            placeholder="Geben Sie hier Ihre Nachricht ein..."
          />

          {/* Priorität und Kategorie */}
          <Box display="flex" gap={2}>
            <FormControl fullWidth>
              <InputLabel>Priorität</InputLabel>
              <Select
                value={formData.prioritaet}
                onChange={(e) => setFormData(prev => ({ 
                  ...prev, 
                  prioritaet: e.target.value as any 
                }))}
                label="Priorität"
              >
                {prioritaeten.map(prioritaet => (
                  <MenuItem key={prioritaet.value} value={prioritaet.value}>
                    <Chip 
                      label={prioritaet.label} 
                      color={prioritaet.color as any} 
                      size="small" 
                    />
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <FormControl fullWidth>
              <InputLabel>Kategorie</InputLabel>
              <Select
                value={formData.kategorie}
                onChange={(e) => setFormData(prev => ({ 
                  ...prev, 
                  kategorie: e.target.value as any 
                }))}
                label="Kategorie"
              >
                {kategorien.map(kategorie => (
                  <MenuItem key={kategorie.value} value={kategorie.value}>
                    {kategorie.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Box>

          {/* Checkbox-Optionen */}
          <Box className="space-y-2">
            <FormControlLabel
              control={
                <Checkbox
                  checked={formData.leseBestaetigungErforderlich}
                  onChange={(e) => setFormData(prev => ({ 
                    ...prev, 
                    leseBestaetigungErforderlich: e.target.checked 
                  }))}
                />
              }
              label="Empfänger sollen Lesen bestätigen"
            />

            <FormControlLabel
              control={
                <Checkbox
                  checked={formData.archivierungErzwingen}
                  onChange={(e) => setFormData(prev => ({ 
                    ...prev, 
                    archivierungErzwingen: e.target.checked 
                  }))}
                />
              }
              label="Nachricht wird nicht gelöscht (Archivierung)"
            />

            <FormControlLabel
              control={
                <Checkbox
                  checked={formData.autoProtokollAnhaengen}
                  onChange={(e) => setFormData(prev => ({ 
                    ...prev, 
                    autoProtokollAnhaengen: e.target.checked 
                  }))}
                />
              }
              label="Tagesprotokoll automatisch anhängen"
            />
          </Box>

          {/* KI-Vorschläge */}
          {showKIVorschlaege && kiVorschlaege.length > 0 && (
            <Box>
              <Button
                variant="outlined"
                onClick={() => setShowVorschlaege(!showVorschlaege)}
                className="mb-2"
              >
                🤖 KI-Vorschläge anzeigen ({kiVorschlaege.length})
              </Button>

              {showVorschlaege && (
                <Card variant="outlined" className="mt-2">
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      KI-Vorschläge
                    </Typography>
                    <Box className="space-y-2">
                      {kiVorschlaege.map((vorschlag, index) => (
                        <Box key={index} className="p-3 border rounded-lg hover:bg-gray-50 cursor-pointer" onClick={() => handleKIVorschlag(vorschlag)}>
                          <Typography variant="subtitle2" className="font-semibold">
                            {vorschlag.betreff}
                          </Typography>
                          <Typography variant="body2" color="text.secondary" className="mt-1">
                            {vorschlag.inhalt.substring(0, 100)}...
                          </Typography>
                          <Box display="flex" gap={1} className="mt-2">
                            <Chip label={vorschlag.empfaengerGruppe} size="small" />
                            <Chip label={`${(vorschlag.konfidenz * 100).toFixed(0)}%`} size="small" color="primary" />
                          </Box>
                        </Box>
                      ))}
                    </Box>
                  </CardContent>
                </Card>
              )}
            </Box>
          )}

          <Divider />

          {/* Aktions-Buttons */}
          <Box display="flex" gap={2} justifyContent="flex-end">
            <Button
              variant="outlined"
              onClick={handleTagesprotokollEinfuegen}
              disabled={loading}
              startIcon={loading ? <CircularProgress size={16} /> : null}
            >
              📋 Tagesprotokoll einfügen
            </Button>

            <Button
              type="submit"
              variant="contained"
              disabled={loading}
              startIcon={loading ? <CircularProgress size={16} /> : null}
            >
              {loading ? 'Sende...' : '✉️ Senden'}
            </Button>
          </Box>
        </form>
      </CardContent>
    </Card>
  );
};

export default NachrichtenFormular;

