                      helperText={errors.delivery_time_days?.message}
                      onChange={(e) => field.onChange(parseInt(e.target.value) || 0)}
                    />
                  )}
                />
              </Grid>
            </Grid>
          )}

          {activeTab === 6 && (
            <Grid container spacing={3}>
              {/* Status */}
              <Grid item xs={12} md={6}>
                <Controller
                  name="status"
                  control={control}
                  render={({ field }) => (
                    <FormControl fullWidth error={!!errors.status}>
                      <InputLabel>Status *</InputLabel>
                      <Select {...field} label="Status *">
                        <MenuItem value="active">
                          <Chip label="Aktiv" color="success" size="small" sx={{ mr: 1 }} />
                          Aktiv
                        </MenuItem>
                        <MenuItem value="inactive">
                          <Chip label="Inaktiv" color="default" size="small" sx={{ mr: 1 }} />
                          Inaktiv
                        </MenuItem>
                        <MenuItem value="discontinued">
                          <Chip label="Eingestellt" color="error" size="small" sx={{ mr: 1 }} />
                          Eingestellt
                        </MenuItem>
                        <MenuItem value="new">
                          <Chip label="Neu" color="primary" size="small" sx={{ mr: 1 }} />
                          Neu
                        </MenuItem>
                      </Select>
                      {errors.status && (
                        <FormHelperText>{errors.status.message}</FormHelperText>
                      )}
                    </FormControl>
                  )}
                />
              </Grid>

              {/* Artikel-Typen */}
              <Grid item xs={12}>
                <Typography variant="h6" fontWeight={600} mb={2}>
                  Artikel-Typen
                </Typography>
                <Stack direction="row" spacing={3}>
                  <Controller
                    name="is_service"
                    control={control}
                    render={({ field }) => (
                      <FormControlLabel
                        control={
                          <Switch
                            checked={field.value}
                            onChange={field.onChange}
                            color="primary"
                          />
                        }
                        label="Dienstleistung"
                      />
                    )}
                  />
                  <Controller
                    name="is_digital"
                    control={control}
                    render={({ field }) => (
                      <FormControlLabel
                        control={
                          <Switch
                            checked={field.value}
                            onChange={field.onChange}
                            color="primary"
                          />
                        }
                        label="Digital"
                      />
                    )}
                  />
                  <Controller
                    name="is_hazardous"
                    control={control}
                    render={({ field }) => (
                      <FormControlLabel
                        control={
                          <Switch
                            checked={field.value}
                            onChange={field.onChange}
                            color="error"
                          />
                        }
                        label="Gefahrgut"
                      />
                    )}
                  />
                </Stack>
              </Grid>

              {/* Kostenstelle */}
              <Grid item xs={12} md={6}>
                <Controller
                  name="cost_center"
                  control={control}
                  render={({ field }) => (
                    <TextField
                      {...field}
                      label="Kostenstelle"
                      fullWidth
                      error={!!errors.cost_center}
                      helperText={errors.cost_center?.message}
                    />
                  )}
                />
              </Grid>

              {/* Profit Center */}
              <Grid item xs={12} md={6}>
                <Controller
                  name="profit_center"
                  control={control}
                  render={({ field }) => (
                    <TextField
                      {...field}
                      label="Profit Center"
                      fullWidth
                      error={!!errors.profit_center}
                      helperText={errors.profit_center?.message}
                    />
                  )}
                />
              </Grid>

              {/* Steuercode */}
              <Grid item xs={12} md={6}>
                <Controller
                  name="tax_code"
                  control={control}
                  render={({ field }) => (
                    <TextField
                      {...field}
                      label="Steuercode"
                      fullWidth
                      error={!!errors.tax_code}
                      helperText={errors.tax_code?.message}
                    />
                  )}
                />
              </Grid>

              {/* Notizen */}
              <Grid item xs={12}>
                <Controller
                  name="notes"
                  control={control}
                  render={({ field }) => (
                    <TextField
                      {...field}
                      label="Notizen"
                      multiline
                      rows={4}
                      fullWidth
                      error={!!errors.notes}
                      helperText={errors.notes?.message}
                    />
                  )}
                />
              </Grid>
            </Grid>
          )}

          {/* Form Actions */}
          <Box display="flex" justifyContent="flex-end" gap={2} mt={4}>
            <NeuroFlowButton
              variant="outlined"
              onClick={handleCancel}
              disabled={submitLoading}
              startIcon={<CancelIcon />}
            >
              Abbrechen
            </NeuroFlowButton>
            <NeuroFlowButton
              type="submit"
              variant="contained"
              disabled={submitLoading || loading}
              startIcon={submitLoading ? <CircularProgress size={20} /> : <SaveIcon />}
            >
              {submitLoading ? 'Speichern...' : 'Artikel speichern'}
            </NeuroFlowButton>
          </Box>
        </form>
      </CardContent>
    </NeuroFlowCard>
  );
};

export default NeuroFlowArticleForm;

