// NeuroFlow Article Table Component
export const NeuroFlowArticleTable: React.FC<NeuroFlowArticleTableProps> = ({
  articles = mockArticles,
  loading = false,
  onAdd,
  onEdit,
  onDelete,
  onView,
  onRefresh,
  onExport,
}) => {
  // State Management
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [sortBy, setSortBy] = useState<keyof Article>('name');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');

  // Filter and Sort Logic
  const filteredAndSortedArticles = useMemo(() => {
    const filtered = articles.filter((article) => {
      const matchesSearch = 
        article.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        article.article_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
        article.brand?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        article.description?.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesCategory = !categoryFilter || article.category === categoryFilter;
      const matchesStatus = !statusFilter || article.status === statusFilter;

      return matchesSearch && matchesCategory && matchesStatus;
    });

    // Sorting
    filtered.sort((a, b) => {
      const aValue = a[sortBy];
      const bValue = b[sortBy];

      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortOrder === 'asc' 
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue);
      }

      if (typeof aValue === 'number' && typeof bValue === 'number') {
        return sortOrder === 'asc' ? aValue - bValue : bValue - aValue;
      }

      return 0;
    });

    return filtered;
  }, [articles, searchTerm, categoryFilter, statusFilter, sortBy, sortOrder]);

  // Pagination
  const paginatedArticles = filteredAndSortedArticles.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  // Utility Functions
  const getStatusColor = (status: Article['status']) => {
    switch (status) {
      case 'active': return 'success';
      case 'inactive': return 'default';
      case 'discontinued': return 'error';
      case 'new': return 'primary';
      default: return 'default';
    }
  };

  const getStatusLabel = (status: Article['status']) => {
    switch (status) {
      case 'active': return 'Aktiv';
      case 'inactive': return 'Inaktiv';
      case 'discontinued': return 'Eingestellt';
      case 'new': return 'Neu';
      default: return status;
    }
  };

  const getStockStatus = (current: number, min: number) => {
    if (current <= 0) return { color: 'error', icon: <ErrorIcon />, label: 'Nicht verfügbar' };
    if (current <= min) return { color: 'warning', icon: <WarningIcon />, label: 'Niedrig' };
    return { color: 'success', icon: <CheckCircleIcon />, label: 'Verfügbar' };
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('de-DE', {
      style: 'currency',
      currency: 'EUR',
    }).format(amount);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('de-DE');
  };

  const getCategories = () => {
    const categories = Array.from(new Set(articles.map(a => a.category)));
    return categories.sort();
  };

  // Event Handlers
  const handleChangePage = (event: unknown, newPage: number) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleSort = (property: keyof Article) => {
    const isAsc = sortBy === property && sortOrder === 'asc';
    setSortOrder(isAsc ? 'desc' : 'asc');
    setSortBy(property);
  };

  const handleDelete = (article: Article) => {
    if (window.confirm(`Artikel "${article.name}" wirklich löschen?`)) {
      onDelete?.(article);
    }
  };

  return (
    <NeuroFlowCard>
      <CardContent>
        {/* Header */}
        <Box display="flex" alignItems="center" justifyContent="space-between" mb={3}>
          <Box display="flex" alignItems="center" gap={2}>
            <InventoryIcon color="primary" sx={{ fontSize: 32 }} />
            <Box>
              <Typography variant="h5" fontWeight={600} color="text.primary">
                Artikelverwaltung
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Verwalten Sie alle Artikel und Produkte im System
              </Typography>
            </Box>
          </Box>

          <Stack direction="row" spacing={1}>
            <Tooltip title="Aktualisieren">
              <IconButton onClick={onRefresh} color="primary" disabled={loading}>
                <RefreshIcon />
              </IconButton>
            </Tooltip>
            <Tooltip title="Exportieren">
              <IconButton onClick={onExport} color="primary">
                <DownloadIcon />
              </IconButton>
            </Tooltip>
            <NeuroFlowButton
              variant="contained"
              onClick={onAdd}
              startIcon={<AddIcon />}
            >
              Neuer Artikel
            </NeuroFlowButton>
          </Stack>
        </Box>

        {/* Filters */}
        <Box mb={3}>
          <Grid container spacing={2} alignItems="center">
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                placeholder="Artikel suchen..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon />
                    </InputAdornment>
                  ),
                }}
              />
            </Grid>
            <Grid item xs={12} md={3}>
              <FormControl fullWidth>
                <InputLabel>Kategorie</InputLabel>
                <Select
                  value={categoryFilter}
                  onChange={(e) => setCategoryFilter(e.target.value)}
                  label="Kategorie"
                >
                  <MenuItem value="">Alle Kategorien</MenuItem>
                  {getCategories().map((category) => (
                    <MenuItem key={category} value={category}>
                      {category}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={3}>
              <FormControl fullWidth>
                <InputLabel>Status</InputLabel>
                <Select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                  label="Status"
                >
                  <MenuItem value="">Alle Status</MenuItem>
                  <MenuItem value="active">Aktiv</MenuItem>
                  <MenuItem value="inactive">Inaktiv</MenuItem>
                  <MenuItem value="discontinued">Eingestellt</MenuItem>
                  <MenuItem value="new">Neu</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={2}>
              <Box display="flex" gap={1}>
                <Chip 
                  label={`${filteredAndSortedArticles.length} Artikel`} 
                  color="primary" 
                  variant="outlined"
                />
              </Box>
            </Grid>
          </Grid>
        </Box>

        {/* Table */}
        <TableContainer component={Paper} sx={{ borderRadius: 2 }}>
          <Table>
            <TableHead>
              <TableRow sx={{ backgroundColor: 'grey.50' }}>
                <TableCell>
                  <Box display="flex" alignItems="center" gap={1}>
                    <InventoryIcon sx={{ fontSize: 20 }} />
                    Artikel
                  </Box>
                </TableCell>
                <TableCell>Kategorie</TableCell>
                <TableCell>Preise</TableCell>
                <TableCell>
                  <Box display="flex" alignItems="center" gap={1}>
                    <StorageIcon sx={{ fontSize: 20 }} />
                    Bestand
                  </Box>
                </TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Lieferant</TableCell>
                <TableCell>Typ</TableCell>
                <TableCell align="right">Aktionen</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                // Loading Skeletons
                Array.from({ length: rowsPerPage }).map((_, index) => (
                  <TableRow key={`skeleton-${index}`}>
                    <TableCell>
                      <Box display="flex" alignItems="center" gap={2}>
                        <Skeleton variant="circular" width={40} height={40} />
                        <Box>
                          <Skeleton variant="text" width={120} height={20} />
                          <Skeleton variant="text" width={80} height={16} />
                        </Box>
                      </Box>
                    </TableCell>
                    <TableCell><Skeleton variant="text" width={80} /></TableCell>
                    <TableCell><Skeleton variant="text" width={60} /></TableCell>
                    <TableCell><Skeleton variant="text" width={40} /></TableCell>
                    <TableCell><Skeleton variant="text" width={60} /></TableCell>
                    <TableCell><Skeleton variant="text" width={80} /></TableCell>
                    <TableCell><Skeleton variant="text" width={60} /></TableCell>
                    <TableCell align="right">
                      <Skeleton variant="rectangular" width={80} height={32} />
                    </TableCell>
                  </TableRow>
                ))
              ) : paginatedArticles.length === 0 ? (
                // Empty State
                <TableRow>
                  <TableCell colSpan={8}>
                    <Box textAlign="center" py={4}>
                      <InfoIcon sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
                      <Typography variant="h6" color="text.secondary" mb={1}>
                        Keine Artikel gefunden
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        {searchTerm || categoryFilter || statusFilter 
                          ? 'Versuchen Sie andere Suchkriterien'
                          : 'Erstellen Sie Ihren ersten Artikel'
                        }
                      </Typography>
                    </Box>
                  </TableCell>
                </TableRow>
              ) : (
                // Article Rows
                paginatedArticles.map((article) => {
                  const stockStatus = getStockStatus(article.current_stock, article.min_stock);

                  return (
                    <TableRow key={article.id} hover>
                      <TableCell>
                        <Box display="flex" alignItems="center" gap={2}>
                          <Avatar sx={{ bgcolor: 'primary.main' }}>
                            <InventoryIcon />
                          </Avatar>
                          <Box>
                            <Typography variant="subtitle2" fontWeight={600}>
                              {article.name}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                              {article.article_number}
                            </Typography>
                            {article.brand && (
                              <Typography variant="caption" color="text.secondary" display="block">
                                {article.brand}
                              </Typography>
                            )}
                          </Box>
                        </Box>
                      </TableCell>

                      <TableCell>
                        <Chip 
                          label={article.category} 
                          size="small" 
                          variant="outlined"
                          icon={<CategoryIcon />}
                        />
                      </TableCell>

                      <TableCell>
                        <Box>
                          <Typography variant="body2" fontWeight={600}>
                            {formatCurrency(article.selling_price)}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            EK: {formatCurrency(article.purchase_price)}
                          </Typography>
                        </Box>
                      </TableCell>

                      <TableCell>
                        <Box display="flex" alignItems="center" gap={1}>
                          <Tooltip title={stockStatus.label}>
                            <IconButton size="small" color={stockStatus.color as any}>
                              {stockStatus.icon}
                            </IconButton>
                          </Tooltip>
                          <Box>
                            <Typography variant="body2" fontWeight={600}>
                              {article.current_stock} {article.unit}
                            </Typography>
                            {article.current_stock <= article.min_stock && (
                              <Typography variant="caption" color="warning.main">
                                Min: {article.min_stock}
                              </Typography>
                            )}
                          </Box>
                        </Box>
                      </TableCell>

                      <TableCell>
                        <Chip 
                          label={getStatusLabel(article.status)}
                          color={getStatusColor(article.status) as any}
                          size="small"
                        />
                      </TableCell>

                      <TableCell>
                        {article.supplier_name ? (
                          <Typography variant="body2">
                            {article.supplier_name}
                          </Typography>
                        ) : (
                          <Typography variant="body2" color="text.secondary">
                            -
                          </Typography>
                        )}
                      </TableCell>

                      <TableCell>
                        <Stack direction="row" spacing={0.5}>
                          {article.is_service && (
                            <Chip label="Service" size="small" color="info" />
                          )}
                          {article.is_digital && (
                            <Chip label="Digital" size="small" color="secondary" />
                          )}
                          {article.is_hazardous && (
                            <Chip label="Gefahrgut" size="small" color="error" />
                          )}
                        </Stack>
                      </TableCell>

                      <TableCell align="right">
                        <Stack direction="row" spacing={0.5}>
                          <Tooltip title="Anzeigen">
                            <IconButton 
                              size="small" 
                              onClick={() => onView?.(article)}
                              color="primary"
                            >
                              <ViewIcon />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="Bearbeiten">
                            <IconButton 
                              size="small" 
                              onClick={() => onEdit?.(article)}
                              color="primary"
                            >
                              <EditIcon />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="Löschen">
                            <IconButton 
                              size="small" 
                              onClick={() => handleDelete(article)}
                              color="error"
                            >
                              <DeleteIcon />
                            </IconButton>
                          </Tooltip>
                        </Stack>
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </TableContainer>

        {/* Pagination */}
        <TablePagination
          rowsPerPageOptions={[5, 10, 25, 50]}
          component="div"
          count={filteredAndSortedArticles.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          labelRowsPerPage="Zeilen pro Seite:"
          labelDisplayedRows={({ from, to, count }) => 
            `${from}-${to} von ${count !== -1 ? count : `mehr als ${to}`}`
          }
        />
      </CardContent>
    </NeuroFlowCard>
  );
};

