    const month = String(date.getMonth() + 1).padStart(2, '0');
    const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
    const customerNumber = `K${year}${month}-${random}`;
    setValue('customer_number', customerNumber);
  };

