    { label: 'Grunddaten', icon: <PersonIcon /> },
    { label: 'Kontaktdaten', icon: <EmailIcon /> },
    { label: 'Adressdaten', icon: <LocationIcon /> },
    { label: 'Bankdaten', icon: <BankIcon /> },
    { label: 'Geschäftsdaten', icon: <BusinessIcon /> },
    { label: 'Notizen', icon: <SettingsIcon /> },
