              {/* Lieferadresse gleich wie Rechnungsadresse */}
              <Grid item xs={12}>
                <Controller
                  name="delivery_address_same"
                  control={control}
                  render={({ field }) => (
                    <Alert severity="info" sx={{ mb: 2 }}>
                      Lieferadresse ist identisch mit Rechnungsadresse
