/**
 * Standardisierte Status-Chip-Komponente
 */
export const StatusChip: React.FC<{
  status: keyof typeof UI_LABELS.STATUS;
  size?: 'small' | 'medium';
  variant?: 'filled' | 'outlined';
}> = ({ status, size = 'medium', variant = 'filled' }) => {
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ACTIVE':
      case 'COMPLETED':
      case 'APPROVED':
      case 'READY':
      case 'DELIVERED':
        return 'success';
      case 'PENDING':
      case 'PROCESSING':
      case 'IN_PROGRESS':
      case 'SCHEDULED':
        return 'warning';
      case 'CANCELLED':
      case 'REJECTED':
      case 'DELETED':
      case 'EXPIRED':
      case 'OVERDUE':
        return 'error';
      case 'DRAFT':
      case 'INACTIVE':
      case 'SUSPENDED':
      case 'ON_HOLD':
        return 'default';
      default:
        return 'primary';
    }
  };

  return (
    <Chip
      label={UI_LABELS.STATUS[status]}
      color={getStatusColor(status) as any}
      size={size}
      variant={variant}
      sx={{ fontWeight: 500 }}
    />
  );
};

/**
 * Standardisierte Prioritäts-Chip-Komponente
 */
export const PriorityChip: React.FC<{
  priority: keyof typeof UI_LABELS.PRIORITY;
  size?: 'small' | 'medium';
  variant?: 'filled' | 'outlined';
}> = ({ priority, size = 'medium', variant = 'filled' }) => {
  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'LOW':
        return 'default';
      case 'MEDIUM':
        return 'primary';
      case 'HIGH':
        return 'warning';
      case 'URGENT':
      case 'CRITICAL':
        return 'error';
      default:
        return 'primary';
    }
  };

  return (
    <Chip
      label={UI_LABELS.PRIORITY[priority]}
      color={getPriorityColor(priority) as any}
      size={size}
      variant={variant}
      sx={{ fontWeight: 500 }}
    />
  );
};

/**
 * Standardisierte Meldungs-Komponente
 */
export const StandardMessage: React.FC<{
  type: 'success' | 'error' | 'warning' | 'info';
  title?: string;
  message: string;
  onClose?: () => void;
  showIcon?: boolean;
}> = ({ type, title, message, onClose, showIcon = true }) => {
  const getIcon = () => {
    if (!showIcon) return null;

    switch (type) {
      case 'success':
        return <SuccessIcon />;
      case 'error':
        return <ErrorIcon />;
      case 'warning':
        return <WarningIcon />;
      case 'info':
        return <InfoIcon />;
      default:
        return <InfoIcon />;
    }
  };

  return (
    <Alert
      severity={type}
      onClose={onClose}
      icon={getIcon()}
      sx={{ 
        borderRadius: 2,
        '& .MuiAlert-message': {
          width: '100%'
        }
      }}
    >
      {title && (
        <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 0.5 }}>
          {title}
        </Typography>
      )}
      {message}
    </Alert>
  );
};

/**
 * Standardisierte Info-Tooltip-Komponente
 */
export const InfoTooltip: React.FC<{
  title: string;
  children: React.ReactNode;
  placement?: 'top' | 'bottom' | 'left' | 'right';
  size?: 'small' | 'medium' | 'large';
}> = ({ title, children, placement = 'top', size = 'small' }) => {
  return (
    <Tooltip title={title} placement={placement} arrow>
      <Box component="span" sx={{ display: 'inline-flex', alignItems: 'center' }}>
        {children}
        <IconButton size={size} sx={{ ml: 0.5, color: 'text.secondary' }}>
          <InfoIcon fontSize={size} />
        </IconButton>
      </Box>
    </Tooltip>
  );
};

/**
 * Standardisierte Hilfe-Komponente
 */
export const HelpButton: React.FC<{
  title: string;
  content: string;
  placement?: 'top' | 'bottom' | 'left' | 'right';
}> = ({ title, content, placement = 'top' }) => {
  return (
    <Tooltip
      title={
        <Box>
          <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 0.5 }}>
            {title}
          </Typography>
          <Typography variant="body2">
            {content}
          </Typography>
        </Box>
      }
      placement={placement}
      arrow
    >
      <IconButton size="small" sx={{ color: 'text.secondary' }}>
        <HelpIcon fontSize="small" />
      </IconButton>
    </Tooltip>
  );
};

/**
 * Hook für UI-Standardisierung
 */
export const useUIStandardization = () => {
  return {
    labels: UI_LABELS,
    getLabel: (path: string) => {
      const keys = path.split('.');
      let value: any = UI_LABELS;

      for (const key of keys) {
        if (value && typeof value === 'object' && key in value) {
          value = value[key];
        } else {
          return path; // Fallback: return original path if not found
        }
      }

      return typeof value === 'string' ? value : path;
    }
  };
};

export default {
  UI_LABELS,
  StatusChip,
  PriorityChip,
  StandardMessage,
  InfoTooltip,
  HelpButton,
  useUIStandardization
};

