                          <ListItemText
                            primary="Beschreibung"
                            secondary={uiMetadata.table.description}
                          />
                        </ListItem>
                        <ListItem>
                          <ListItemText
                            primary="Aktionen"
                            secondary={uiMetadata.table.actions.join(', ')}
                          />
                        </ListItem>
                      </List>
                    </Box>
                  )}

                  {uiMetadata.form && (
                    <Box>
                      <Typography variant="subtitle2" className="mb-2">
                        Formular-Konfiguration:
