import { useState, useEffect } from 'react';

// Debounce Hook für VALEO NeuroERP
export const useDebounce = <T>(value: T, delay: number): T => {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
};

// Debounced Callback Hook
export const useDebouncedCallback = <T extends (...args: any[]) => any>(
  callback: T,
  delay: number
): T => {
  const [debounceTimer, setDebounceTimer] = useState<NodeJS.Timeout | null>(null);

  const debouncedCallback = ((...args: Parameters<T>) => {
    if (debounceTimer) {
      clearTimeout(debounceTimer);
    }

    const timer = setTimeout(() => {
      callback(...args);
    }, delay);

    setDebounceTimer(timer);
  }) as T;

  useEffect(() => {
    return () => {
      if (debounceTimer) {
        clearTimeout(debounceTimer);
      }
    };
  }, [debounceTimer]);

  return debouncedCallback;
};

// Debounced State Hook
export const useDebouncedState = <T>(initialValue: T, delay: number) => {
  const [value, setValue] = useState<T>(initialValue);
  const [debouncedValue, setDebouncedValue] = useState<T>(initialValue);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return [value, setValue, debouncedValue] as const;
};

/**
 * Dual MCP React Hooks für VALEO NeuroERP
 * Kombiniert Schema- und UI-Metadata für optimale Komponenten-Entwicklung
 */

import { useState, useEffect, useCallback } from 'react';
import { useForm, type UseFormReturn } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import dualMCPClient, { 
  type MCPSchema, 
  type CompleteMetadata, 
  type UIFieldMetadata 
} from '../utils/dualMCPClient';

// Hook für kombinierte Metadaten
export interface UseDualMCPMetadataReturn {
  schema: MCPSchema | null;
  uiMetadata: CompleteMetadata | null;
  combined: any;
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

export const useDualMCPMetadata = (tableName: string): UseDualMCPMetadataReturn => {
  const [schema, setSchema] = useState<MCPSchema | null>(null);
  const [uiMetadata, setUIMetadata] = useState<CompleteMetadata | null>(null);
  const [combined, setCombined] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchMetadata = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const result = await dualMCPClient.getCombinedMetadata(tableName);

      setSchema(result.schema);
      setUIMetadata(result.uiMetadata);
      setCombined(result.combined);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unbekannter Fehler');
      console.error(`Error fetching dual MCP metadata for ${tableName}:`, err);
    } finally {
      setLoading(false);
    }
  }, [tableName]);

  useEffect(() => {
    fetchMetadata();
  }, [fetchMetadata]);

  return {
    schema,
    uiMetadata,
    combined,
    loading,
    error,
    refetch: fetchMetadata
  };
};

// Hook für Schema-basierte Formulare mit UI-Metadata
export interface UseDualMCPFormReturn<T = any> extends UseFormReturn<T> {
  schema: MCPSchema | null;
  uiMetadata: CompleteMetadata | null;
  enhancedFields: UIFieldMetadata[];
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

export const useDualMCPForm = <T = any>(
  tableName: string,
  defaultValues?: Partial<T>
): UseDualMCPFormReturn<T> => {
  const { schema, uiMetadata, combined, loading, error, refetch } = useDualMCPMetadata(tableName);

  // Zod-Schema generieren
  const zodSchema = combined ? dualMCPClient.generateZodSchema(combined) : z.object({});

  // React Hook Form mit Zod-Resolver
  const form = useForm<T>({
    resolver: zodResolver(zodSchema) as any,
    defaultValues: (defaultValues || {}) as any
  });

  // Erweiterte Felder mit UI-Metadata
  const enhancedFields = combined?.enhanced_fields || [];

  return {
    ...form,
    schema,
    uiMetadata,
    enhancedFields,
    loading,
    error,
    refetch
  };
};

// Hook für Schema-basierte Tabellen mit UI-Metadata
export interface UseDualMCPTableReturn {
  schema: MCPSchema | null;
  uiMetadata: CompleteMetadata | null;
  tableMetadata: any;
  enhancedFields: UIFieldMetadata[];
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

export const useDualMCPTable = (tableName: string): UseDualMCPTableReturn => {
  const { schema, uiMetadata, combined, loading, error, refetch } = useDualMCPMetadata(tableName);

  const tableMetadata = uiMetadata?.table || null;
  const enhancedFields = combined?.enhanced_fields || [];

  return {
    schema,
    uiMetadata,
    tableMetadata,
    enhancedFields,
    loading,
    error,
    refetch
  };
};

// Hook für CRUD-Operationen mit RLS-Compliance
export interface UseDualMCPDataReturn<T = any> {
  data: T[] | null;
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
  create: (item: Omit<T, 'id'>) => Promise<T>;
  update: (id: string, item: Partial<T>) => Promise<T>;
  delete: (id: string) => Promise<void>;
}

export const useDualMCPData = <T = any>(tableName: string): UseDualMCPDataReturn<T> => {
  const [data, setData] = useState<T[] | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { schema, uiMetadata } = useDualMCPMetadata(tableName);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      // Mock-Daten basierend auf Schema (später durch echte API ersetzen)
      const mockData = generateMockData<T>(schema, tableName);
      setData(mockData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unbekannter Fehler');
      console.error(`Error fetching data for ${tableName}:`, err);
    } finally {
      setLoading(false);
    }
  }, [schema, tableName]);

  const create = useCallback(async (item: Omit<T, 'id'>): Promise<T> => {
    try {
      setLoading(true);
      setError(null);

      // Mock-Create (später durch echte API ersetzen)
      const newItem = {
        ...item,
        id: Math.random().toString(36).substr(2, 9),
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      } as T;

      setData(prev => prev ? [...prev, newItem] : [newItem]);
      return newItem;
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Fehler beim Erstellen');
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const update = useCallback(async (id: string, item: Partial<T>): Promise<T> => {
    try {
      setLoading(true);
      setError(null);

      // Mock-Update (später durch echte API ersetzen)
      setData(prev => {
        if (!prev) return null;
        return prev.map(existingItem => {
          if ((existingItem as any).id === id) {
            return {
              ...existingItem,
              ...item,
              updated_at: new Date().toISOString()
            };
          }
          return existingItem;
        });
      });

      const updatedItem = data?.find(item => (item as any).id === id);
      if (!updatedItem) throw new Error('Item nicht gefunden');

      return updatedItem;
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Fehler beim Aktualisieren');
      throw err;
    } finally {
      setLoading(false);
    }
  }, [data]);

  const deleteItem = useCallback(async (id: string): Promise<void> => {
    try {
      setLoading(true);
      setError(null);

      // Mock-Delete (später durch echte API ersetzen)
      setData(prev => prev ? prev.filter(item => (item as any).id !== id) : null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Fehler beim Löschen');
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return {
    data,
    loading,
    error,
    refetch: fetchData,
    create,
    update,
    delete: deleteItem
  };
};

// Hook für automatische Komponenten-Generierung
export interface UseDualMCPComponentReturn {
  formComponent: string;
  tableComponent: string;
  loading: boolean;
  error: string | null;
  regenerate: () => Promise<void>;
}

export const useDualMCPComponent = (tableName: string): UseDualMCPComponentReturn => {
  const [formComponent, setFormComponent] = useState<string>('');
  const [tableComponent, setTableComponent] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { combined, loading: metadataLoading, error: metadataError } = useDualMCPMetadata(tableName);

  const generateComponents = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      if (combined) {
        const formCode = dualMCPClient.generateReactComponent(combined, 'form');
        const tableCode = dualMCPClient.generateReactComponent(combined, 'table');

        setFormComponent(formCode);
        setTableComponent(tableCode);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Fehler bei der Komponenten-Generierung');
      console.error(`Error generating components for ${tableName}:`, err);
    } finally {
      setLoading(false);
    }
  }, [combined, tableName]);

  useEffect(() => {
    if (!metadataLoading && !metadataError) {
      generateComponents();
    }
  }, [metadataLoading, metadataError, generateComponents]);

  return {
    formComponent,
    tableComponent,
    loading: loading || metadataLoading,
    error: error || metadataError,
    regenerate: generateComponents
  };
};

// Hilfsfunktion für Mock-Daten-Generierung
function generateMockData<T>(schema: MCPSchema | null, tableName: string): T[] {
  if (!schema) return [];

  const mockData: T[] = [];
  const mockCount = 5; // Anzahl Mock-Einträge

  for (let i = 1; i <= mockCount; i++) {
    const item: any = {
      id: `${tableName}_${i}`,
      created_at: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString(),
      updated_at: new Date().toISOString()
    };

    // Felder basierend auf Schema generieren
    schema.columns.forEach(column => {
      if (column.name === 'id') return; // Bereits gesetzt

      switch (column.type.toLowerCase()) {
        case 'uuid':
          item[column.name] = `uuid-${i}-${Math.random().toString(36).substr(2, 9)}`;
          break;
        case 'email':
          item[column.name] = `user${i}@example.com`;
          break;
        case 'int':
        case 'integer':
        case 'bigint':
          item[column.name] = Math.floor(Math.random() * 1000);
          break;
        case 'numeric':
        case 'decimal':
        case 'real':
          item[column.name] = parseFloat((Math.random() * 1000).toFixed(2));
          break;
        case 'boolean':
          item[column.name] = Math.random() > 0.5;
          break;
        case 'date':
          item[column.name] = new Date(Date.now() - Math.random() * 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
          break;
        case 'timestamp':
        case 'timestamptz':
          item[column.name] = new Date(Date.now() - Math.random() * 365 * 24 * 60 * 60 * 1000).toISOString();
          break;
        case 'enum':
          if (column.enum_values && column.enum_values.length > 0) {
            item[column.name] = column.enum_values[Math.floor(Math.random() * column.enum_values.length)];
          } else {
            item[column.name] = 'default';
          }
          break;
        default:
          // Text-basierte Felder
          if (column.name.toLowerCase().includes('name')) {
            item[column.name] = `Test ${column.name} ${i}`;
          } else if (column.name.toLowerCase().includes('description')) {
            item[column.name] = `Beschreibung für ${column.name} ${i}`;
          } else if (column.name.toLowerCase().includes('status')) {
            item[column.name] = ['aktiv', 'inaktiv', 'wartung'][Math.floor(Math.random() * 3)];
          } else {
            item[column.name] = `Wert ${i}`;
          }
      }
    });

    mockData.push(item as T);
  }

  return mockData;
}

import { useState, useEffect } from 'react';

interface UseLocalStorageOptions {
  serialize?: (value: unknown) => string;
  deserialize?: (value: string) => unknown;
}

const defaultOptions: UseLocalStorageOptions = {
  serialize: JSON.stringify,
  deserialize: JSON.parse,
};

export function useLocalStorage<T>(
  key: string,
  initialValue: T,
  options: UseLocalStorageOptions = {}
): [T, (value: T | ((val: T) => T)) => void] {
  const { serialize, deserialize } = { ...defaultOptions, ...options };

  // State to store our value
  // Pass initial state function to useState so logic is only executed once
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === 'undefined') {
      return initialValue;
    }

    try {
      const item = window.localStorage.getItem(key);
      return item ? (deserialize!(item) as T) : initialValue;
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  // Return a wrapped version of useState's setter function that ...
  // ... persists the new value to localStorage.
  const setValue = (value: T | ((val: T) => T)) => {
    try {
      // Allow value to be a function so we have the same API as useState
      const valueToStore = value instanceof Function ? value(storedValue) : value;

      // Save state
      setStoredValue(valueToStore);

      // Save to local storage
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, serialize!(valueToStore));
      }
    } catch (error) {
      console.error(`Error setting localStorage key "${key}":`, error);
    }
  };

  return [storedValue, setValue];
}

// Hook for managing multiple localStorage items
export function useLocalStorageMulti<T extends Record<string, unknown>>(
  keys: (keyof T)[],
  initialValues: T
): [T, (updates: Partial<T>) => void] {
  const [values, setValues] = useState<T>(() => {
    if (typeof window === 'undefined') {
      return initialValues;
    }

    const result = { ...initialValues };

    keys.forEach((key) => {
      try {
        const item = window.localStorage.getItem(String(key));
        if (item) {
          result[key] = JSON.parse(item) as T[keyof T];
        }
      } catch (error) {
        console.error(`Error reading localStorage key "${String(key)}":`, error);
      }
    });

    return result;
  });

  const setValue = (updates: Partial<T>) => {
    const newValues = { ...values, ...updates };
    setValues(newValues);

    if (typeof window !== 'undefined') {
      Object.entries(updates).forEach(([key, value]) => {
        try {
          window.localStorage.setItem(key, JSON.stringify(value));
        } catch (error) {
          console.error(`Error setting localStorage key "${key}":`, error);
        }
      });
    }
  };

  return [values, setValue];
}

// Hook for managing localStorage with expiration
export function useLocalStorageWithExpiry<T>(
  key: string,
  initialValue: T,
  expiryInMinutes: number = 60
): [T | null, (value: T) => void] {
  const [storedValue, setStoredValue] = useState<T | null>(() => {
    if (typeof window === 'undefined') {
      return null;
    }

    try {
      const item = window.localStorage.getItem(key);
      if (!item) return null;

      const parsedItem = JSON.parse(item) as { value: T; expiry: number };

      if (Date.now() > parsedItem.expiry) {
        window.localStorage.removeItem(key);
        return null;
      }

      return parsedItem.value;
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error);
      return null;
    }
  });

  const setValue = (value: T) => {
    try {
      const item = {
        value,
        expiry: Date.now() + (expiryInMinutes * 60 * 1000),
      };

      setStoredValue(value);

      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(item));
      }
    } catch (error) {
      console.error(`Error setting localStorage key "${key}":`, error);
    }
  };

  return [storedValue, setValue];
}

// Hook for managing localStorage with encryption (basic)
export function useLocalStorageEncrypted<T>(
  key: string,
  initialValue: T,
  password: string
): [T, (value: T) => void] {
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === 'undefined') {
      return initialValue;
    }

    try {
      const item = window.localStorage.getItem(key);
      if (!item) return initialValue;

      // Basic encryption/decryption (for production, use a proper encryption library)
      const decrypted = atob(item);
      const parsed = JSON.parse(decrypted) as T;
      return parsed;
    } catch (error) {
      console.error(`Error reading encrypted localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  const setValue = (value: T) => {
    try {
      // Basic encryption (for production, use a proper encryption library)
      const encrypted = btoa(JSON.stringify(value));

      setStoredValue(value);

      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, encrypted);
      }
    } catch (error) {
      console.error(`Error setting encrypted localStorage key "${key}":`, error);
    }
  };

  return [storedValue, setValue];
}

// Hook for managing localStorage with validation
export function useLocalStorageWithValidation<T>(
  key: string,
  initialValue: T,
  validator: (value: unknown) => value is T
): [T, (value: T) => void] {
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === 'undefined') {
      return initialValue;
    }

    try {
      const item = window.localStorage.getItem(key);
      if (!item) return initialValue;

      const parsed = JSON.parse(item) as unknown;

      if (validator(parsed)) {
        return parsed;
      } else {
        console.warn(`Invalid data in localStorage key "${key}", using initial value`);
        return initialValue;
      }
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  const setValue = (value: T) => {
    try {
      if (!validator(value)) {
        throw new Error(`Invalid value for localStorage key "${key}"`);
      }

      setStoredValue(value);

      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(value));
      }
    } catch (error) {
      console.error(`Error setting localStorage key "${key}":`, error);
    }
  };

  return [storedValue, setValue];
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useForm, FieldValues, UseFormReturn, FieldError, FieldErrors, Path, PathValue, DefaultValues, Resolver } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { getMCPSchemaInjector } from '../utils/mcpSchemaInjector';
import type { MCPSchema } from '../utils/mcpSchemaInjector';

interface MCPFormConfig<T extends FieldValues> {
  schema?: z.ZodSchema<T>;
  defaultValues?: DefaultValues<T>;
  mode?: 'onBlur' | 'onChange' | 'onSubmit' | 'onTouched' | 'all';
  reValidateMode?: 'onBlur' | 'onChange' | 'onSubmit' | 'onTouched' | 'all';
  criteriaMode?: 'firstError' | 'all';
}

interface MCPFormState<T extends FieldValues> {
  isDirty: boolean;
  isSubmitting: boolean;
  isSubmitted: boolean;
  isValid: boolean;
  errors: FieldErrors<T>;
  touchedFields: Record<string, boolean>;
}

interface MCPFormActions<T extends FieldValues> {
  reset: (values?: DefaultValues<T>) => void;
  setValue: (name: Path<T>, value: PathValue<T, Path<T>>) => void;
  getValues: () => T;
  trigger: (name?: Path<T> | Path<T>[]) => Promise<boolean>;
  clearErrors: (name?: Path<T> | Path<T>[]) => void;
  setError: (name: Path<T>, error: FieldError) => void;
}

export function useMCPForm<T extends FieldValues = FieldValues>(
  config: MCPFormConfig<T> = {}
): UseFormReturn<T> & MCPFormState<T> & MCPFormActions<T> {
  const {
    schema,
    defaultValues,
    mode = 'onBlur',
    reValidateMode = 'onChange',
    criteriaMode = 'firstError'
  } = config;

  const resolver: Resolver<T> | undefined = schema ? zodResolver(schema as any) : undefined;

  const form = useForm<T>({
    defaultValues: defaultValues as DefaultValues<T>,
    mode,
    reValidateMode: reValidateMode as 'onBlur' | 'onChange' | 'onSubmit',
    criteriaMode,
    resolver
  });

  const [formState, setFormState] = useState<MCPFormState<T>>({
    isDirty: false,
    isSubmitting: false,
    isSubmitted: false,
    isValid: false,
    errors: {} as FieldErrors<T>,
    touchedFields: {}
  });

  const previousValues = useRef<T>(form.getValues());

  // Form State synchronisieren
  useEffect(() => {
    const subscription = form.watch((value) => {
      const currentValues = value as T;
      const isDirty = JSON.stringify(currentValues) !== JSON.stringify(previousValues.current);

      setFormState(prev => ({
        ...prev,
        isDirty,
        isValid: form.formState.isValid,
        errors: form.formState.errors,
        touchedFields: form.formState.touchedFields as Record<string, boolean>
      }));

      previousValues.current = currentValues;
    });

    return () => subscription.unsubscribe();
  }, [form]);

  // Reset Funktion
  const reset = useCallback((values?: DefaultValues<T>) => {
    form.reset(values as any);
    setFormState(prev => ({
      ...prev,
      isDirty: false,
      isSubmitted: false,
      errors: {} as FieldErrors<T>,
      touchedFields: {}
    }));
  }, [form]);

  // SetValue Funktion
  const setValue = useCallback((name: Path<T>, value: PathValue<T, Path<T>>) => {
    form.setValue(name, value as any);
  }, [form]);

  // GetValues Funktion
  const getValues = useCallback(() => {
    return form.getValues();
  }, [form]);

  // Trigger Funktion
  const trigger = useCallback(async (name?: Path<T> | Path<T>[]) => {
    return await form.trigger(name);
  }, [form]);

  // ClearErrors Funktion
  const clearErrors = useCallback((name?: Path<T> | Path<T>[]) => {
    form.clearErrors(name);
  }, [form]);

  // SetError Funktion
  const setError = useCallback((name: Path<T>, error: FieldError) => {
    form.setError(name, error);
  }, [form]);

  return {
    ...form,
    ...formState,
    reset,
    setValue,
    getValues: getValues as any,
    trigger,
    clearErrors,
    setError
  };
}

// Specialized hooks for common form patterns
export function useMCPFormWithValidation<T extends FieldValues>(
  schema: z.ZodSchema<T>,
  defaultValues?: DefaultValues<T>
) {
  return useMCPForm<T>({
    schema,
    defaultValues
  });
}

export function useMCPFormWithAutoSave<T extends FieldValues>(
  schema: z.ZodSchema<T>,
  defaultValues?: DefaultValues<T>,
  autoSaveDelay: number = 1000
) {
  const form = useMCPForm<T>({
    schema,
    defaultValues
  });

  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const autoSave = useCallback(async () => {
    if (form.isDirty && form.isValid) {
      setIsSaving(true);
      try {
        // Hier würde die tatsächliche Speicherlogik implementiert
        await new Promise(resolve => setTimeout(resolve, 500));
        setLastSaved(new Date());
        form.reset(form.getValues());
      } catch (error) {
        console.error('Auto-Save fehlgeschlagen:', error);
      } finally {
        setIsSaving(false);
      }
    }
  }, [form]);

  useEffect(() => {
    const timeoutId = setTimeout(autoSave, autoSaveDelay);
    return () => clearTimeout(timeoutId);
  }, [form.watch(), autoSave, autoSaveDelay]);

  return {
    ...form,
    lastSaved,
    isSaving
  };
}

export function useMCPFormWithSteps<T extends FieldValues>(
  steps: Array<{
    id: string;
    title: string;
    fields: (keyof T)[];
    validation?: z.ZodSchema<Partial<T>>;
  }>,
  defaultValues?: DefaultValues<T>
) {
  const form = useMCPForm<T>({
    defaultValues
  });

  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState<Set<number>>(new Set());

  const currentStepConfig = steps[currentStep];
  const isFirstStep = currentStep === 0;
  const isLastStep = currentStep === steps.length - 1;

  const validateCurrentStep = useCallback(async () => {
    if (currentStepConfig?.validation) {
      try {
        const stepFields = form.getValues();
        currentStepConfig.validation.parse(stepFields);
        return true;
      } catch (error) {
        if (error instanceof z.ZodError) {
          const zodError = error as z.ZodError;
          (zodError as any).errors.forEach((err: any) => {
            const fieldName = err.path.join('.') as Path<T>;
            form.setError(fieldName, {
              type: 'validation',
              message: err.message
            });
          });
        }
        return false;
      }
    }
    return true;
  }, [currentStepConfig, form]);

  const nextStep = useCallback(async () => {
    const isValid = await validateCurrentStep();
    if (isValid && !isLastStep) {
      setCompletedSteps(prev => new Set([...prev, currentStep]));
      setCurrentStep(prev => prev + 1);
    }
  }, [validateCurrentStep, isLastStep, currentStep]);

  const prevStep = useCallback(() => {
    if (!isFirstStep) {
      setCurrentStep(prev => prev - 1);
    }
  }, [isFirstStep]);

  const goToStep = useCallback((stepIndex: number) => {
    if (stepIndex >= 0 && stepIndex < steps.length) {
      setCurrentStep(stepIndex);
    }
  }, [steps.length]);

  const isStepCompleted = useCallback((stepIndex: number) => {
    return completedSteps.has(stepIndex);
  }, [completedSteps]);

  return {
    ...form,
    currentStep,
    currentStepConfig,
    isFirstStep,
    isLastStep,
    nextStep,
    prevStep,
    goToStep,
    isStepCompleted,
    completedSteps: Array.from(completedSteps)
  };
}

// Hook for form with conditional fields
export function useMCPFormWithConditionalFields<T extends FieldValues>(
  schema: z.ZodSchema<T>,
  defaultValues?: DefaultValues<T>,
  conditionalLogic?: Record<keyof T, (values: T) => boolean>
) {
  const form = useMCPForm<T>({
    schema,
    defaultValues
  });

  const [visibleFields, setVisibleFields] = useState<Set<keyof T>>(new Set());

  useEffect(() => {
    if (conditionalLogic) {
      const values = form.getValues();
      const newVisibleFields = new Set<keyof T>();

      Object.entries(conditionalLogic).forEach(([field, condition]) => {
        if (condition(values)) {
          newVisibleFields.add(field as keyof T);
        }
      });

      setVisibleFields(newVisibleFields);
    }
  }, [form.watch(), conditionalLogic, form]);

  const isFieldVisible = useCallback((field: keyof T) => {
    if (!conditionalLogic) return true;
    return visibleFields.has(field);
  }, [visibleFields, conditionalLogic]);

  return {
    ...form,
    isFieldVisible,
    visibleFields: Array.from(visibleFields)
  };
}

// Hook for form with file uploads
export function useMCPFormWithFileUpload<T extends FieldValues>(
  schema: z.ZodSchema<T>,
  defaultValues?: DefaultValues<T>
) {
  const form = useMCPForm<T>({
    schema,
    defaultValues
  });

  const [uploadedFiles, setUploadedFiles] = useState<Record<string, File[]>>({});

  const handleFileUpload = useCallback((fieldName: keyof T, files: FileList | File[]) => {
    const fileArray = Array.from(files);
    setUploadedFiles(prev => ({
      ...prev,
      [fieldName as string]: fileArray
    }));

    // Update form value
    form.setValue(fieldName as Path<T>, fileArray as PathValue<T, Path<T>>);
  }, [form]);

  const removeFile = useCallback((fieldName: keyof T, fileIndex: number) => {
    setUploadedFiles(prev => {
      const fieldFiles = prev[fieldName as string] || [];
      const newFiles = fieldFiles.filter((_, index) => index !== fileIndex);

      return {
        ...prev,
        [fieldName as string]: newFiles
      };
    });
  }, []);

  const clearFiles = useCallback((fieldName: keyof T) => {
    setUploadedFiles(prev => {
      const newFiles = { ...prev };
      delete newFiles[fieldName as string];
      return newFiles;
    });

    form.setValue(fieldName as Path<T>, [] as PathValue<T, Path<T>>);
  }, [form]);

  return {
    ...form,
    uploadedFiles,
    handleFileUpload,
    removeFile,
    clearFiles
  };
}

/**
 * React Hook für MCP-Tabellen
 */
export function useMCPTable<T = unknown>(tableName: string) {
  const [schema, setSchema] = useState<MCPSchema | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const mcpInjector = getMCPSchemaInjector();

  useEffect(() => {
    const loadSchema = async () => {
      try {
        setIsLoading(true);
        setError(null);

        const loadedSchema = await mcpInjector.getTableSchema(tableName);
        setSchema(loadedSchema);

      } catch (err) {
        const error = err instanceof Error ? err : new Error('Unbekannter Fehler');
        setError(error);
      } finally {
        setIsLoading(false);
      }
    };

    loadSchema();
  }, [tableName, mcpInjector]);

  const getVisibleColumns = useCallback(() => {
    if (!schema) return [];
    return schema.columns.filter(col => !col.primary || col.type !== 'uuid');
  }, [schema]);

  const getEditableColumns = useCallback(() => {
    if (!schema) return [];
    return schema.columns.filter(col => 
      !col.primary && 
      col.type !== 'uuid' && 
      !col.name.includes('created_at') && 
      !col.name.includes('updated_at')
    );
  }, [schema]);

  const canDelete = useCallback(() => {
    return schema?.rls?.delete || false;
  }, [schema]);

  return {
    schema,
    isLoading,
    error,
    getVisibleColumns,
    getEditableColumns,
    canDelete
  };
}

