                    <TableCell>
                      <Chip
                        label={form.complexity}
                        size="small"
                        color={
                          form.complexity === 'high' ? 'error' :
                          form.complexity === 'medium' ? 'warning' : 'success'
                        }
                      />
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={form.status}
                        size="small"
                        color={
                          form.status === 'active' ? 'success' :
                          form.status === 'draft' ? 'warning' :
                          form.status === 'deprecated' ? 'error' : 'default'
                        }
                      />
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2">
                        {form.version}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2">
                        {form.priority}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', gap: 1 }}>
                        <Tooltip title="Erstellen">
                          <IconButton
                            size="small"
                            onClick={() => openForm(form.id, 'create')}
                            color="primary"
                          >
                            <AddIcon />
                          </IconButton>
                        </Tooltip>
                        <Tooltip title="Bearbeiten">
                          <IconButton
                            size="small"
                            onClick={() => openForm(form.id, 'edit')}
                            color="primary"
                          >
                            <EditIcon />
                          </IconButton>
                        </Tooltip>
                        <Tooltip title="Anzeigen">
                          <IconButton
                            size="small"
                            onClick={() => openForm(form.id, 'view')}
                            color="info"
                          >
                            <ViewIcon />
                          </IconButton>
                        </Tooltip>
                        <Tooltip title="Testen">
                          <IconButton
                            size="small"
                            onClick={() => openForm(form.id, 'create')}
                            color="success"
                          >
                            <PlayIcon />
                          </IconButton>
                        </Tooltip>
                      </Box>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>
    );
  };

  /**
   * Rendert die Modul-Übersicht
   */
  const renderModuleOverview = () => {
    if (!statistics) return null;

    return (
      <Grid container spacing={3}>
        {Object.entries(statistics.byModule).map(([module, count]) => (
          <Grid item xs={12} sm={6} md={3} key={module}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  {module.charAt(0).toUpperCase() + module.slice(1)}
                </Typography>
                <Typography variant="h4" component="div" color="primary">
                  {count}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  Formulare
                </Typography>
              </CardContent>
              <CardActions>
                <Button
                  size="small"
                  onClick={() => setFilterOptions(prev => ({ ...prev, module }))}
                >
                  Anzeigen
                </Button>
              </CardActions>
            </Card>
          </Grid>
        ))}
      </Grid>
    );
  };

  /**
   * Rendert die Komplexitäts-Übersicht
   */
  const renderComplexityOverview = () => {
    if (!statistics) return null;

    return (
      <Grid container spacing={3}>
        {Object.entries(statistics.byComplexity).map(([complexity, count]) => (
          <Grid item xs={12} sm={6} md={4} key={complexity}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  {complexity === 'high' ? 'Hohe Komplexität' :
                   complexity === 'medium' ? 'Mittlere Komplexität' : 'Niedrige Komplexität'}
                </Typography>
                <Typography variant="h4" component="div" color="primary">
                  {count}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  Formulare
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    );
  };

  /**
   * Rendert die Formular-Details
   */
  const renderFormDetails = () => {
    if (!selectedForm) return null;

    const form = formTableService.getFormEntry(selectedForm);
    if (!form) return null;

    return (
      <Card>
        <CardContent>
          <Typography variant="h5" gutterBottom>
            {form.title}
          </Typography>
          <Typography variant="body1" color="textSecondary" paragraph>
            {form.description}
          </Typography>

          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <Typography variant="h6" gutterBottom>
                Basis-Informationen
              </Typography>
              <Typography variant="body2">
                <strong>ID:</strong> {form.id}
              </Typography>
              <Typography variant="body2">
                <strong>Modul:</strong> {form.module}
              </Typography>
              <Typography variant="body2">
                <strong>Kategorie:</strong> {form.category}
              </Typography>
              <Typography variant="body2">
                <strong>Version:</strong> {form.version}
              </Typography>
              <Typography variant="body2">
                <strong>Status:</strong> {form.status}
              </Typography>
            </Grid>

            <Grid item xs={12} md={6}>
              <Typography variant="h6" gutterBottom>
                Technische Details
              </Typography>
              <Typography variant="body2">
                <strong>Komplexität:</strong> {form.complexity}
              </Typography>
              <Typography variant="body2">
                <strong>Priorität:</strong> {form.priority}
              </Typography>
              <Typography variant="body2">
                <strong>Komponenten-Pfad:</strong> {form.componentPath}
              </Typography>
              <Typography variant="body2">
                <strong>Validierung:</strong> {form.validationSchema}
              </Typography>
              <Typography variant="body2">
                <strong>Accessibility:</strong> {form.accessibilityLevel}
              </Typography>
            </Grid>
          </Grid>

          <Box sx={{ mt: 2 }}>
            <Typography variant="h6" gutterBottom>
              Tags
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              {form.tags.map((tag, index) => (
                <Chip key={index} label={tag} size="small" />
              ))}
            </Box>
          </Box>

          <Box sx={{ mt: 2 }}>
            <Typography variant="h6" gutterBottom>
              Abhängigkeiten
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              {form.dependencies.map((dependency, index) => (
                <Chip key={index} label={dependency} size="small" variant="outlined" />
              ))}
            </Box>
          </Box>
        </CardContent>
      </Card>
    );
  };

  // Tab-Panels
  const tabPanels = [
    {
      label: 'Übersicht',
      icon: <StatsIcon />,
      content: (
        <Box>
          {renderStatisticsCards()}
          <Typography variant="h5" gutterBottom>
            Modul-Übersicht
          </Typography>
          {renderModuleOverview()}
          <Typography variant="h5" gutterBottom sx={{ mt: 4 }}>
            Komplexitäts-Übersicht
          </Typography>
          {renderComplexityOverview()}
        </Box>
      )
    },
    {
      label: 'Formulare',
      icon: <ViewIcon />,
      content: (
        <Box>
          {renderFilters()}
          {renderFormTable()}
        </Box>
      )
    },
    {
      label: 'Form Manager',
      icon: <SettingsIcon />,
      content: (
        <Box>
          <FormManager />
        </Box>
      )
    },
    {
      label: 'Details',
      icon: <EditIcon />,
      content: (
        <Box>
          {renderFormDetails()}
        </Box>
      )
    }
  ];

  // Loading-Zustand
  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '50vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  // Error-Zustand
  if (error) {
    return (
      <Alert severity="error" sx={{ m: 2 }}>
        {error}
      </Alert>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Vollständige Formular-Demo - VALEO NeuroERP 2.0
      </Typography>
      <Typography variant="body1" color="textSecondary" paragraph>
        Diese Demo zeigt alle implementierten Formulare und Eingabemasken mit vollständiger Funktionalität.
      </Typography>

      {/* Tabs */}
      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={activeTab} onChange={(_, newValue) => setActiveTab(newValue)}>
          {tabPanels.map((tab, index) => (
            <Tab
              key={index}
              label={tab.label}
              icon={tab.icon}
              iconPosition="start"
            />
          ))}
        </Tabs>
      </Box>

      {/* Tab-Inhalte */}
      {tabPanels[activeTab].content}

      {/* Formular-Dialog */}
      {showFormDialog && selectedForm && (
        <ModernERPForm
          config={{
            id: selectedForm,
            metadata: {
              id: selectedForm,
              name: `Formular ${selectedForm}`,
              module: 'demo',
              version: '1.0.0',
